COLLDATA("silsila","ur",[[3585,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس وقت تک شب و روز کا سلسلہ ختم نہیں ہوگا، جب تک لات و عزی کی عبادت نہیں کی جائے گی۔“ سیدہ عائشہ نے کہا: اے اللہ کے رسول! جب اللہ تعالی نے یہ آیت نازل کی: ﴿اسی نے رسول کو ہدایت اور سچے دین کے ساتھ بھیجا ہے کہ اسے دوسرے تمام مذہبوں پر غالب کر دے، اگرچہ مشرک برا مانیں۔﴾۝ (سورۂ توبہ: ۳۳) تو مجھے گمان ہوا کہ یہ دین اب مکمل رہے گا (اور کوئی خرابی پیدا نہیں ہوگی)۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جب تک اللہ چاہے گا، دین مکمل رہے گا۔“","",{"t":"علاماتِ قیامت","k":"رواه مسلم وغيره، وقد خرجته في \"تحذير الساجد من اتخاذ القبور مساجد\": ص ۱۲۲، وأخرجه الحافظ الداني في \"الفتن\": ق ۸۵ - ۵۹\n(الصحيحة: ۱)","e":"صحیح مسلم کی مکمل روایت یوں ہے: (جب سیدہ عائشہ رضی اللہ عنہا نے آیت پیش کر کے اپنا استدلال ذکر کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا:) ”جب تک اللہ تعالیٰ چاہے گا، دین قائم رہے گا، پھر اللہ تعالی پاکیزہ پاکیزہ ہوا چلائے گا، اس کی وجہ سے ہر وہ شخص فوت ہو جائے گا، جس کے دل میں رائی کے دانے کے برابر ایمان ہوگا، (اس واقعہ کے بعد) ایسے لوگ باقی رہ جائیں گے، جن میں کوئی خیر نہیں ہوگی، پھر یہ اپنے آبا و اجداد کے دین کی طرف لوٹ جائیں گے۔“"}],[3586,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”شب و روز کا سلسلہ اس وقت تک ختم نہیں ہوگا، جب تک جہجاہ نامی غلام بادشاہ نہیں بنے گا۔“","",{"t":"علاماتِ قیامت","k":"أخرجه مسلم: ۸/ ۱۸۴، والترمذي: ۲۲۲۹، وأحمد: ۲/ ۳۲۹، والثقفي في \"مشيخة النيسابورين\": ق ۱/ ۱۹۲\n(الصحيحة: ۲۴۴۱)"}],[3587,"رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت سے قبل تم ایسے لوگوں سے قتال کرو گے جن کے جوتے بالوں کے ہوں گے اور یہی لوگ ہیں مسلمانوں سے لڑنے والے۔“ یہ حدیث سیدنا ابو ہریرہ، سیدنا عمرو بن تغلب اور سیدنا ابو سعید خدری رضی اللہ عنہم سے مروی ہے۔","",{"t":"علاماتِ قیامت","k":"جاء من حديث أبي هريرة، وعمرو بن تغلب، وأبي سعيد الخدري: (۱) أما حديث أبي هريرة، فله عنه طرق: رواه البخاري: ۲۹۲۸، ۲۹۲۹، ۳۰۵۷، ۳۰۵۸، ومسلم: ۸/ ۱۸۴، وأبو داود: ۴۳۰۴، والترمذي: ۲۲۱۵، وابن حبان: ۶۷۴۶، والحميدي: ۱۱۰۰، وأبو يعلى: ۵۸۷۸، وعبدالرزاق: ۲۰۷۸۱، وعنه أحمد: ۲/ ۲۷۱، وابن ماجه: ۴۰۹۶، وابن ماجه: ۴۰۹۷ (۲)۔ أما حديث عمرو بن تغلب: فرواه البخاري: ۲۹۲۷، ۳۵۹۲، وابن ماجه: ۴۰۹۸، وأحمد: ۵/ ۶۹ و ۷۰، وابن قانع في \"معجم الصحابة\": ۲/ ۲۱۲، وأبو نعيم في \"المعرفة\": ق ۱/ ۸۷ (۳) وأما حديث ابي سعيد: فهو مخرجه في \"الصحيحة\": برقم ۲۴۲۹\n(الصحيحة: ۳۶۰۹)","e":"ایک روایت میں ہے کہ ان کے لباس بھی بالوں کے ہوں گے، کیونکہ ان کے علاقے زیادہ برف باری ہونے کی وجہ سے بہت زیادہ سرد ہیں، یہی لباس ان کے لیے زیادہ مفید ہے۔ ملا علی قاری نے کہا ہے کہ بالوں سے مراد دباغت کے بغیر وہ چمڑے ہیں، جن پر بال لگے ہوئے ہوں۔"}],[3588,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس وقت تک قیامت قائم نہیں ہوگی جب تک تم چھوٹی آنکھوں اور چوڑے چہروں والوں سے قتال نہ کر لو گے، گویا کہ ان کی آنکھیں مکڑی کی سیاہی کی طرح ہوں گی اور ان کے چہرے گویا کہ تہ بر تہ چڑھائی ہوئی ڈھالیں ہیں، وہ بالوں کے جوتے پہنیں گے، چمڑے کی ڈھالیں استعمال کریں گے اور اپنے گھوڑوں کو کھجوروں کے ساتھ باندھیں گے۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۳/ ۳۱، وابن ماجه: ۴۰۹۹، وابن حبان: ۱۸۷۲\n(الصحيحة: ۲۴۲۹)","e":"امام نووی کہتے ہیں: یہ رسول اللہ صلی اللہ علیہ وسلم کے معجزات تھے، یہ ترک لوگ تھے، احادیث میں مذکورہ تمام صفات ان میں پائی جاتی تھیں، مسلمان ان سے کئی دفعہ لڑے اور اب بھی لڑ رہے ہیں، ہم اللہ تعالی سے سوال کرتے ہیں کہ مسلمانوں کا انجام بخیر و عافیت ہو۔ (شرح مسلم للنووی: ۲/ ۳۹۵) ملا علی قاری نے کہا: سدی کہتے ہیں کہ ترک، یاجوج ماجوج کی ایک جماعت ہے، قتادہ کہتے ہیں: یاجوج ماجوج کے کل بائیس قبیلے تھے، ذو القرنین نے اکیس کے سامنے دیوار بنا دی اور یہ ایک قبیلہ باہر رہ گیا، جو ترک تھا۔ (مرقاۃ المفاتيح: ۹/ ۲۹۹)"}],[3589,"سیدنا ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس وقت تک قیامت قائم نہیں ہوگی، جب تک بیت اللہ کا حج چھوڑ نہ دیا جائے۔“","",{"t":"علاماتِ قیامت","k":"رواه أبو يعلى في \"مسنده\": ۲/ ۶۵، وابن حبان: ۱۸۸۴، والحاكم: ۴/ ۴۵۳، وأخرجه البخاري: ۱/ ۴۰۳ بلفظ: ((لَيُحَجَّنَّ الْبَيْتُ، وَلَيُعْتَمَرَنَّ بَعْدَ خُرُوجِ يَأْجُوجَ وَمَأْجُوجَ)) ثم قال: تابعه أبان وعمران عن قتادة، وقال عبد الرحمن عن شعبة: ((لَا تَقُومُ السَّاعَةُ حَتَّى لَا يُحَجَّ الْبَيْتُ)) والاول اكثر۔\n(الصحيحة: ۲۴۳۰)","e":"امام البانی اس حدیث پر بحث کرتے ہوئے کہتے ہیں: سیدنا ابو سعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «لَيُحَجَّنَّ الْبَيْتُ وَلَيُعْتَمَرَنَّ بَعْدَ خُرُوجِ يَأْجُوجَ وَمَأْجُوجَ -» ...... ”یاجوج و ماجوج کے نکلنے کے بعد بھی بیت اللہ کا حج اور عمرہ کیا جائے گا۔“ پہلی حدیث سے معلوم ہوتا ہے کہ علاماتِ قیامت کے ظہور کے بعد حج نہیں کیا جائے گا، جبکہ دوسری حدیث سے ثابت ہوتا ہے کہ حج کیا جائے گا۔ حقیقت میں ان دو احادیث میں کوئی تعارض نہیں ہے، کیونکہ ممکن ہے کہ یاجوج و ماجوج کے بعد حج و عمرہ کا جو سلسلہ جاری رہے گا، وہ قیامت کے قریب رک جائے گا۔ (صحیحہ: ۲۴۳۰)"}],[3590,"سیدنا ابو موسی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت اس وقت تک قائم نہیں ہوگی، جب تک آدمی اپنے پڑوسی، اپنے بھائی اور اپنے باپ کو قتل نہیں کرے گا۔“","",{"t":"علاماتِ قیامت","k":"أخرجه البخاري في \"الأدب المفرد\": رقم ۱۱۸\n(الصحيحة: ۳۱۸۵)","e":"ایسے واقعات تو اخبار و جرائد میں بارہا چھپ چکے ہیں اور آپ صلی اللہ علیہ وسلم کی پیشین گوئی پوری ہو چکی ہے، دیکھیں مستقبل میں کیا ہوتا ہے۔"}],[3591,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس وقت تک قیامت قائم نہیں ہوگی جب تک ایسا نہ ہو کہ آدمی کسی قبر کے پاس سے گزرے اور اللہ تعالی سے ملاقات کرنے کے شوق کی بنا پر کہے گا: کاش میں اس کی جگہ پر ہوتا۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۲/ ۵۳۰، والحديث أخرجه مالك في \"الموطأ\": ۱/ ۲۳۹، وعنه البخاري: ۱۳/ ۶۳، ومسلم: ۸/ ۱۸۲، وأحمد: ۲/ ۲۳۶ دون قوله: ((مَا بِهِ حُبُّ لِقَاءِ اللهِ عَزَّ وَجَلَّ -))\n(الصحيحة: ۵۷۸)","e":"عصر حاضر میں بعض لوگ ایسی ایسی آزمائشوں میں گھرے ہوئے ہیں کہ وہ موت کی تمنا کرتے ہوئے نظر آتے ہیں۔ خوشحال لوگوں کو ان کی آزمائشوں کا اندازہ نہیں ہو سکتا ہے۔ امام البانی رحمہ اللہ نے کہا: اس حدیث کا مفہوم یہ ہے کہ وہ آدمی اللہ تعالی کا قرب حاصل کرنے اور اس سے ملاقات کرنے کی بنا پر نہیں، بلکہ دنیوی آزمائشوں اور فتنوں کی وجہ سے موت کی تمنا کرے گا۔ لیکن اس حدیث سے یہ اشارہ ضرور ملتا ہے کہ دین کی خاطر موت کی تمنا کی جا سکتی ہے، رہا مسئلہ اس حدیث مبارکہ کا کہ «لَا يَتَمَنَّيَنَّ أَحَدُكُمُ الْمَوْتَ لِضُرٍّ نَزَلَ بِهِ -» ...... ”کوئی آدمی کسی تکلیف کی بنا پر موت کی تمنا نہ کرے۔“ کیونکہ یہ صورت دنیوی معاملے کے ساتھ خاص ہے۔ حافظ ابن حجر نے کہا: سلف کی ایک جماعت کے نزدیک فساد دین کے وقت موت کی تمنا کرنا ثابت ہے، اس سے سیدنا ابو ہریرہ رضی اللہ عنہ کی درج بالا حدیث کی تائید ہوتی ہے۔ امام نووی نے کہا: ایسے وقت میں موت کی تمنا کرنا مکروہ نہیں ہے، کیونکہ کئی سلف صالحین نے ایسے کیا ہے، جیسا سیدنا عمر بن خطاب رضی اللہ عنہ ...... (صحیحہ: ۵۷۸) امام البانی کے دعوے کی تصدیق صحیح مسلم کی روایت کے الفاظ سے ہوتی ہے: «وَالَّذِي نَفْسِي بِيَدِهِ! لَا تَذْهَبُ الدُّنْيَا حَتَّى يَمُرَّ الرَّجُلُ عَلَى الْقَبْرِ فَيَتَمَرَّغُ عَلَيْهِ، وَيَقُولُ: يَا لَيْتَنِي كُنْتُ مَكَانَ صَاحِبِ هَذَا الْقَبْرِ وَلَيْسَ بِهِ الدِّينُ إِلَّا الْبَلَاءُ -» ...... ”اس ذات کی قسم جس کے ہاتھ میری جان ہے! اس وقت تک دنیا ختم نہیں ہوگی، جب تک ایسے نہ ہوگا کہ ایک آدمی ایک قبر کے پاس سے گزرے گا، اس پر لیٹے گا اور کہے گا: ہائے کاش! میں اس قبر والے کی جگہ پر ہوتا، اس کا موت کی تمنا کرنا دین کی بنا پر نہیں ہوگا، آزمائشوں کی وجہ سے ہوگا۔“"}],[3592,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اس وقت تک قیامت قائم نہیں ہوگی، جب تک ایسے نہیں ہوگا کہ عام بارش برسے گی لیکن زمین کوئی (کھیتی) نہیں اگائے گی۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۳/ ۱۴۰، وأبو يعلى: ۳/ ۱۰۷۲، والبخاري في \"التاريخ\": ۴/ ۱/ ۳۶۲\n(الصحيحة: ۲۷۷۳)"}],[3593,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت اس وقت تک قائم نہیں ہوگی، جب تک ایسے نہیں ہوگا کہ بارش برسے گی اور کوئی گارے والا گھر نہیں بچ سکے گا اور اس سے نہیں بچے گا مگر بالوں والا گھر۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۲/ ۲۶۲، وابن حبان في \"صحيحه\": ۸/ ۲۷۰/ ۶۷۳۲\n(الصحيحة: ۳۲۶۶)","e":"امام البانی رحمہ اللہ لکھتے ہیں: اس حدیث کا ظاہری مفہوم درج ذیل حدیث کے مخالف ہے: سیدنا نواس بن سمعان رضی اللہ عنہ یاجوج ماجوج کا قصہ بیان کرتے ہیں، جب اللہ تعالی ان سب کو ہلاک کر دے گا اور ان کے تعفن کی وجہ سے زمین بدبودار ہو جائے گی، پھر اللہ تعالی بارش نازل کریں گے، کوئی گارے والا اور بالوں والا گھر اس سے نہیں بچ سکے گا، ساری زمین دھل جائے گی اور چکنے پتھر (یا آئینے) کی طرح صاف ہو جائے گی۔ (مسلم) اس حدیث میں ہے کہ بالوں والا گھر بھی نہیں بچ سکے گی، جب کہ متن میں والی حدیث میں ایسے گھروں کو مستثنی قرار دیا گیا ہے۔ ممکن ہے کہ دو علیحدہ علیحدہ اوقات میں مختلف بارشیں ہوں۔ واللہ اعلم۔"}],[3594,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے قریب (ہونے کی علامت یہ بھی ہے کہ) چاند بڑا ہو جائے گا، جب ایک رات کا چاند نظر آئے گا تو کہا جائے گا کہ یہ تو دو راتوں کا ہے۔“","",{"t":"علاماتِ قیامت","k":"أخرجه الطبراني في \"المعجم الصغير\": ص ۱۸۲ ورقم ۱۱۳۰۔ الروض النضير، وفي \"الأوسط\": أيضا ۲/ ۱۳۰، ۱/ ۷۰۰۷، و\"مسند الشامين\": ۶۴۰۲\n(الصحيحة: ۲۲۹۲)"}],[3595,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت اس وقت قائم ہوگی جب فتنے ظاہر ہوں گے، جھوٹ عام ہو جائے گا، بازار تنگ ہو جائیں گے، وقت جلدی گزرے گا اور ہرج زیادہ ہوگا۔“ کہا گیا: ہرج کے کیا معانی ہیں؟ فرمایا: ”قتل۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۲/ ۵۱۹\n(الصحيحة: ۲۷۷۲)","e":"بعض مہینوں میں یہ علامت پوری ہوتی ہوئی نظر آتی ہے کہ چاند معمول سے ہٹ کر بڑا معلوم ہوتا ہے۔"}],[3596,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت اس وقت تک برپا نہیں ہوگی جب تک عربوں کی سرزمین سبزہ زاروں اور نہروں کی صورت اختیار نہیں کر لے گی۔“","",{"t":"علاماتِ قیامت","k":"رواه مسلم ۳/ ۸۴، وأحمد: ۲/ ۳۷۰ و ۴۱۷، والحاكم: ۴/ ۴۷۷\n(الصحيحة: ۶)","e":"امام البانی رحمہ اللہ نے کہا: جزیرۂ عرب کے بعض علاقوں میں اس حدیث مبارکہ میں کی گئی پیشین گوئی کے آثار و علامات دکھائی دینے لگے ہیں۔ اللہ تعالی کی خیرات و برکات کے نزول کے کئی مناظر نظر آ رہے ہیں، مختلف آلات کے ذریعے صحرائی زمین سے آبپاشی کے لیے پانی نکالا جا رہا ہے۔ بعض مقامی اخبار میں یہ بات بھی شائع ہوئی تھی کہ فرات کا رخ جزیرۂ عرب کی طرف موڑنے کے منصوبے پر غور کیا جا رہا ہے، ممکن ہے کہ منصوبہ پائے تکمیل تک پہنچ جائے۔ اس مناسبت سے درج ذیل حدیث مبارکہ پر غور کریں: سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «لَا يَأْتِي عَلَيْكَ زَمَانٌ إِلَّا وَالَّذِي بَعْدَهُ شَرٌّ مِنْهُ حَتَّى تَلْقَوْا رَبَّكُمْ -» (صحیح بخاری) ...... ”تم پر جو زمانہ بھی آئے گا، اس کے بعد والا اس سے برا ہوگا، یہاں تک تم اپنے رب سے جا ملو گے۔“ یہ حدیث اپنے عموم پر باقی نہیں ہے، اس کا مطلب یہ نہیں کہ قیامت تک بدتر سے بدتر زمانہ آئے گا، بلکہ اس حدیث کو ان احادیث کی روشنی میں سمجھنا چاہیے، جن میں امام مہدی کی آمد اور حضرت عیسی علیہ السلام کے نزول کی پیشین گوئی کی گئی ہے۔ اس لیے مایوسی میں مبتلا نہیں ہونا چاہیے اور اس انتظار میں رہنا چاہیے کہ اسلام پھر سے دنیا کو بیدار کرنے والا ہے۔ (صحیحہ: ۶)"}],[3597,"سیدنا عبداللہ اور سیدنا ابو موسی رضی اللہ عنہما بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”قیامت سے قبل ایسے ایام بھی ہوں گے کہ ان میں جہالت عام ہو جائے گی، علم کا فقدان ہو جائے گا اور بکثرت قتل ہوں گے۔“ سیدنا ابو موسی کہتے ہیں: ”ہرج“ حبشی زبان کا لفظ ہے، اس کے معانی ”قتل“ کے ہیں۔","",{"t":"علاماتِ قیامت","k":"أخرجه البخاري: ۷۰۶۲، ۷۰۶۳، ۷۰۶۴، ۷۰۶۵، ۷۰۶۶، ومسلم: ۸/ ۵۸، ۵۹، والترمذي: ۲۲۰۰، وابن ماجه: ۴۰۵۰، ۴۰۵۱، وأبو نعيم في \"الحلية\": ۴/ ۱۱۲، وابن أبي شيبة في \"المصنف\": ۱۸۹۷۱، وأحمد: ۱/ ۴۰۲، ۴/ ۳۹۲، ۴۰۵\n(الصحيحة: ۳۰۵۲)","e":"اگر اس دور کا سلف صالحین اور ان کے بعد والے دور سے موازنہ کیا جائے تو واضح طور پر علم شرعی کا شدید فقدان نظر آئے گا، قتل کی کثرت کا معاملہ تو واضح ہے۔ یہاں یہ بات ذہن نشین کرنا ضروری ہے کہ دنیوی تعلیم کی تمام صورتیں ایک فن ہیں، جو دنیا میں مختلف انداز میں معاون ثابت ہوتی ہیں، لیکن اس تعلیم سے تقوی، صالحیت اور اسلامی غیرت کے جذبات اور دین کی سمجھ پیدا نہیں ہوتی، بلکہ بعض لوگوں کو دیکھا گیا ہے کہ وہ اعلی ڈگری حاصل کرنے کے بعد غرور و تکبر میں مبتلا ہو جاتے ہیں۔ غور فرمائیں کہ ہمارے معاشرے میں انگریزی، ریاضی، کیمسٹری، کمپیوٹر، اردو اور دوسرے مضامین میں ماسٹر، ایم فل اور پی ایچ ڈی کی ڈگریوں کے حاملین موجود ہیں، لیکن اگر وہ فہم قرآن سے محروم ہیں، ترجمہ قرآن سے دور ہیں، علم حدیث پر ان کو دسترس حاصل نہیں ہے، اسلامی فقہ کا ان کو تجربہ نہیں ہے، تو یہی کہا جائے گا کہ اس معاشرے میں شرعی علم کا فقدان ہے اور اس میں بسیرا کرنے والے جاہل ہیں، کیونکہ شریعت کی نگاہ اس چیز کو علم کہتے ہیں جو اعمال صالحہ کا سبب بنتا ہے۔ قارئین کرام! محسوس نہ کرنا، راقم الحروف کا ایسے ہزاروں افراد سے واسطہ پڑا، جو اعلی دنیوی تعلیم سے آراستہ ہیں، لیکن نماز جیسے فریضے سے کوسوں دور ہیں، قرآن مجید کی دیکھ کر بھی تلاوت نہیں کر سکتے، اہلیت ہونے کے صورت میں کئی ماہ قرآن مجید کھولنا ان کو نصیب نہیں ہوتا، لیکن اپنے آپ کو اتنا اہلیت والا سمجھتے ہیں کہ گویا ان کے بغیر دنیا بے آسرا ہو جائے گی۔ اگر آپ کو یقین نہیں ہے تو نماز کے وقت میں کسی یونیورسٹی اور اس میں تعمیر شدہ مسجد کا جائزہ لے لیں۔ شریعت میں ایسے معاشرے کی کوئی وقعت نہیں ہے۔"}],[3598,"سیدنا ابو موسی اشعری رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت سے پہلے ”ہرج“ ہوگا۔“ کسی نے پوچھا: ”ہرج“ کا کیا معنی ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اس کا معنی قتل ہے، (ذہن نشین کر لو کہ) اس سے مراد تمہارا مشرکوں کو قتل کرنا نہیں ہے، بلکہ آپس میں ایک دوسرے کو قتل کرنا ہے، (اور بات یہاں تک جا پہنچے گی کہ) آدمی اپنے پڑوسی کو، بھائی کو، چچا کو اور چچا زاد کو قتل کر ڈالے گا۔“ صحابہ نے کہا: کیا اس وقت ہم میں عقل باقی ہوگی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اُس زمانے والوں کی عقلیں سلب کر لی جائیں گی، وہ بیوقوف لوگ ہوں گے، ان کی اکثریت اپنے آپ کو بزعم خود کسی حقیقت پر خیال کرے گی، لیکن وہ کسی حقیقت پر نہیں ہوں گے۔“ سیدنا ابو موسی نے کہا: اس ذات کی قسم جس کے ہاتھ میں میری جان ہے! اگر ایسے ایام ہم کو پا لیں تو ان سے راہ فرار کا ایک ہی طریقہ ہوگا کہ جیسے ہم داخل ہوئے ایسے ہی وہاں سے نکل آئیں، نہ کسی کا خون بہائیں اور نہ کسی کا مال چھینیں۔","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۴/ ۳۹۱، ۴۱۴، وابن ماجه: ۳۹۵۹\n(الصحيحة: ۱۶۸۲)","e":"یقیناً ہمارا معاشرہ اس حدیث کا مصداق بن چکا ہے، قتل اتنا عام ہو گیا کہ ایک ایک دھماکے میں سینکڑوں لوگ کام آ جاتے ہیں۔ محرم رشتہ داروں میں اس قدر دشمنی اور عداوت ہے کہ وہ ایک دوسرے کی جان کے پیاسے نظر آتے ہیں اور موقع ملنے پر اپنی خواہش بد کا اظہار کر دیتے ہیں۔"}],[3599,"سیدنا عبداللہ بن عمرو بن عاص رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے قریب ہونے کی علامت یہ ہے کہ بدترین لوگوں کو اعلی مناصب دیے جائیں گے، شریف لوگوں کو ذلیل سمجھا جائے گا، لوگ بڑی بڑی باتیں (یعنی بڑکیں) ماریں گے، عمل محدود ہو جائے گا اور لوگوں میں ”مثناۃ“ عام ہوگی، کوئی بھی اس کا انکار نہیں کر سکے گا۔“ کہا گیا کہ ”مثناۃ“ سے کیا مراد ہے؟ فرمایا: ”جو چیز قرآنی (علوم) کے علاوہ لکھی جائے۔“","",{"t":"علاماتِ قیامت","k":"أخرجه الحاكم: ۴/ ۵۵۴، والهيثمي في \"المجمع\": ۷/ ۳۲۶، وابن أبي شيبة في \"المصنف\": ۱۵/ ۱۶۵/ ۱۹۳۹۵، وأبو عمرو الداني في \"الفتن\": ق ۵۳/ ۱ - ۲، والبيهقي في \"الشعب\": ۴/ ۳۰۶/ ۵۱۹۹\n(الصحيحة: ۲۸۲۱)","e":"مسلم ممالک میں صدارت و وزارتِ عظمی جیسے بڑے بڑے عہدوں پر فائز ہونے والوں اور قومی اور صوبائی اسمبلیوں کے امیدواروں اور دوسرے اعلی عہدے داروں کی مذہبی حالت کیا ہے؟ یہ فیصلہ شریعت کی روشنی میں کیا جائے گا۔ ان کے مقابلے میں لوگوں کو خیر و بھلائی کی تعلیم دینے والوں، بچوں کو قرآن مجید کی ناظرہ، حفظ اور ترجمہ کی تعلیم دینے والوں، مساجد میں خطابت و امامت کے منصب کو سنبھالنے والوں، اذان دینے والوں، مسجد کی صفائی کرنے والوں اور نکاح، فتوی اور نماز جنازہ جیسی ذمہ داریوں کو نبھانے والوں کا کیا مقام ہے؟ یہ فیصلہ بھی شریعت کی روشنی میں کیا جائے گا۔ اگر سچ پوچھیں تو صرف نماز پڑھانا اور قرآن مجید کی تعلیم دینا اتنا عظیم اور جلیل عمل ہے کہ بظاہر اس عمل کا مقابلہ کرنے کے لیے عوام کے پاس کوئی مقابل موجود نہیں ہے، اس پر مستزاد یہ کہ عوام کی نمازوں اور تلاوتوں کا ثواب بھی پہلے ان مسجد والوں کے کھاتے میں آتا ہے، کیونکہ یہ ان کی تعلیم کا نتیجہ ہوتا ہے۔ بہرحال آپ صلی اللہ علیہ وسلم کی پیشین گوئی ثابت ہوئی اور حالات بدل گئے، اب احترام تو ہوگا، لیکن مال کی وجہ سے، نسب کی وجہ سے، حسن کی وجہ سے، عہدے کی وجہ سے، سیاسی موافقت کی وجہ سے، دنیوی تعلیم کی وجہ سے، پرانی یاری کی وجہ سے۔ اس وجہ سے نہیں کہ فلاں نمازی ہے، روزانہ تلاوت کرتا ہے، حافظ قرآن ہے، بچوں کو حفظ و ناظرہ اور احادیث رسول کی تعلیم دیتا ہے، لوگوں کو نیکی اور سنت کی طرف رغبت دلاتا ہے اور برائی اور بدعت سے منع کرتا ہے، مسجد کی صفائی کرتا ہے۔ رہا مسئلہ معاوضے اور تنخواہ کا، جو عوام کا بہت بڑا اعتراض ہے، تو گزارش ہے کہ کئی لوگ فی سبیل اللہ کام کر رہے ہیں اور کئی لوگ بہت تھوڑی تنخواہ وصول کرتے ہیں، جو کہ ان کے لیے حلال اور جائز ہے۔ امام البانی رحمہ اللہ رقمطراز ہیں: آپ صلی اللہ علیہ وسلم کی نبوت و رسالت کی نشانیوں میں سے ایک نشانی یہ حدیث مبارکہ ہے، اس میں مذکورہ تمام امور وقوع پذیر ہو چکے ہیں، بالخصوص ”مثناۃ“ والا معاملہ۔ لیکن قرآن مجید اور اس کے ساتھ ساتھ احادیثِ نبویہ اور سلف صالحین کے آثار کی کتاب کو مستثنی کر لیا گیا ہے۔ رہا مسئلہ ان فقہی کتب کا، جن میں مقلدین کے فرضی مسائل کا بیان ہے اور جنھوں نے طویل زمانے کی جد و جہد کے بعد لوگوں کی توجہ کو قرآن مجید اور سنتِ رسول سے ہٹا لیا ہے۔ بڑا افسوس ہے کہ آج کل کے اکثر مقلدوں میں یہی چیز نظر آتی ہے، حالانکہ ان میں پی ایچ ڈی کی ڈگری حاصل کرنے والے اور شرعی کلیات سے سندِ فراغت لینے والے بھی موجود ہیں، ان کا مذہب تقلید ہے اور یہ اسے علما سمیت تمام لوگوں کے لیے ضروری خیال کرتے ہیں۔ دیکھیں کہ ان کے سرخیل ابو الحسن کرخی حنفی نے اپنی مشہور قاعدے کا یوں اظہار کیا: کل آیة تخالف ما علیه اصحابنا فهی مؤولة او منسوخة و کل حدیث کذلک فهو مؤول او منسوخ۔ (تاریخ التشریع الاسلامی للشیخ محمد الخضری) ...... ہر وہ آیت، جو ہمارے اصحاب کے مسلک کے مخالف ہے، اس کی تاویل کی جائے گی یا اس کو منسوخ سمجھا جائے گا، اور یہی معاملہ ہر حدیث کا ہے کہ اس کی بھی تاویل کی جائے گی یا پھر اس کو منسوخ سمجھا جائے گا۔ سبحان اللہ! ان لوگوں نے اپنے مذہب کو اصل اور قرآن مجید کو اس کا تابع بنا دیا، یہی وہ ”مُثَنَّاة“ (لکھت پڑھت) ہے، جس کو اس حدیث میں قیامت کی علامت قرار دیا گیا ہے۔ ھدایہ میں اس حدیث کے بعد ”مُثَنَّاة“ کی تفسیر میں یہ کہا گیا ہے: ”اس کے بارے میں ایک قول یہ ہے کہ اس لفظ سے مراد حضرت موسی علیہ السلام کے بعد والے بنو اسرائیل کی اخبار ہیں اور وہ اس طرح کہ ان لوگوں نے اللہ کی کتاب کو ترک کر کے اپنی منشا کے مطابق ایک (خود ساختہ) کتاب ترتیب دی، اسے ”مثناۃ“ کہتے تھے۔ شاید یہی وجہ ہے سیدنا ابن عمرو رضی اللہ عنہ اہل کتاب سے روایت لینے کو ناپسند کرتے ہیں، حالانکہ ان کے پاس ان کی کتابیں موجود تھیں، جو ان کو یرموک والے دن ملی تھیں۔“ میں (البانی) کہتا ہوں: یہ تفسیر اس حدیثِ مبارکہ کے ظاہری مفہوم سے بہت بعید ہے، کیونکہ ”مُثَنَّاة“ تو قریب قیامت کی علامتوں میں سے ہے، اس چیز کا یہودیوں کے اس فعل سے کیا تعلق ہے، جو آپ صلی اللہ علیہ وسلم کی بعثت سے پہلے کیا گیا۔ بلا شک و شبہ ابن اثیر نے ”قیل“ کہہ کر اس تفسیر کے ضعیف ہونے کی طرف اشارہ کر دیا ہے۔ اور اس حدیث کی درج ذیل تفسیر کرنا تو سب سے زیادہ ضعیف ہے: جوہری نے کہا: ”مُثَنَّاة“ سے مراد گانے ہیں، جن کو فارسی میں ”دو بیتی“ کہتے ہیں۔ (صحیحہ: ۲۸۲۱) آخری قطعہ حدیث کا مطلب یہ ہے کہ لوگوں میں اخباروں، ڈائجسٹوں اور کہانیوں جیسی فضول چیزوں کا عام مطالعہ ہوگا، قرآنی علوم کی طرف توجہ دھرنے والا کوئی نہیں ہوگا۔"}],[3600,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”لوگوں پر عنقریب فریبی و مکاری والا زمانہ آئے گا، اس میں جھوٹے کو سچا اور سچے کو جھوٹا سمجھا جائے گا اور خائن کو امین اور امانتدار کو خائن قرار دیا جائے گا اور ”رویبضہ“ قسم کے لوگ (عوام الناس کے امور سے متعلقہ) گفتگو کریں گے۔“ پوچھا گیا کہ ”رویبضہ“ سے کیا مراد ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”معمولی اور کم عقل لوگ جو عوام الناس کے امور پر بحث و مباحثہ کریں گے۔“","",{"t":"علاماتِ قیامت","k":"أخرجه ابن ماجه: ۴۰۴۲، والحاكم: ۴/ ۴۶۵، ۵۱۲، وأحمد: ۲/ ۲۹۱، والخرائطي في \"مكارم الأخلاق\": ص ۳۰\n(الصحيحة: ۱۸۸۷)"}],[3601,"اسود بن یزید کہتے ہیں: مسجد میں نماز کے لیے اقامت کہہ دی گئی، ہم سیدنا عبداللہ بن مسعود رضی اللہ عنہ کے ساتھ مسجد کی طرف چل پڑے، لوگ رکوع کی حالت میں تھے، سیدنا عبداللہ نے (صف تک پہنچنے سے قبل ہی) رکوع کر لیا اور ہم بھی رکوع کے لیے جھک گئے اور رکوع کی حالت میں چل کر (صف میں کھڑے ہو گئے)۔ ایک آدمی سیدنا عبداللہ کے سامنے سے گزرا، اس نے کہا: ابو عبد الرحمن! السلام علیکم۔ سیدنا عبداللہ نے رکوع کی حالت میں ہی کہا: اللہ اور اس کے رسول نے سچ فرمایا۔ جب وہ نماز سے فارغ ہوئے تو بعض افراد نے سوال کیا: جب اُس آدمی نے آپ پر سلام کہا تو آپ نے یہ کیوں کہا: اللہ اور اس کے رسول نے سچ فرمایا؟ انھوں نے جواباً کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”یہ چیز بھی علاماتِ قیامت میں سے ہے کہ سلام معرفت کی بنا پر ہوگا۔“ اور ایک روایت میں ہے: ”ایک آدمی دوسرے کو سلام تو کہے گا، لیکن معرفت کی بنا پر کہے گا۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۱/ ۳۸۷، والطبراني في \"المعجم الكبير\": ۳/ ۳۶/ ۲\n(الصحيحة: ۶۴۸)","e":"اکثر مسلمانوں کا یہی حال ہے کہ ان کا سلام مخصوص افراد کے لیے رہ گیا ہے، جب کہ احادیث کی روشنی میں ہر ایک، وہ معروف ہو یا غیر معروف، کو سلام کہنے کی ترغیب دلائی گئی ہے۔"}],[3602,"سیدنا عمرو بن تغلب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”یہ چیز علاماتِ قیامت میں سے ہے کہ مال پھیل جائے گا، جہالت عام ہو جائے گی، فتنے ابھر پڑیں گے، تجارت عام ہو جائے گی اور علم (یعنی پڑھائی لکھائی) عام ہو گی۔“","",{"t":"علاماتِ قیامت","k":"أخرجه النسائي في \"سننه\": ۲/ ۲۱۲، والحاكم في \"مستدركه\": ۲/ ۷، واللفظ له، والطيالسي: ۱۱۷۱، وعنه ابن منده في \"المعرفة\": ۲/ ۵۹/ ۲، والخطابي في \"غريب الحديث\": ۱/ ۸۲\n(الصحيحة: ۲۷۶۷)","e":"امام البانی رحمہ اللہ لکھتے ہیں: آج کل اکثر حکومتیں ناخواندگی اور ان پڑھی کو ختم کرنے اور پڑھنے لکھنے کا بہت اہتمام کر رہی ہیں اور اس پر خرچ کناں بھی ہیں۔ ہر حکومت یہ اعلان کرتی ہوئی نظر آتی ہے کہ اس کے ہاں ناخوانگی کی شرح نہ ہونے کے برابر ہے۔ اس حدیث مبارکہ میں اس اہتمام کا قوی اشارہ موجود ہے، میرے ماں باپ آپ صلی اللہ علیہ وسلم پر قربان ہوں، یہ حدیث آپ صلی اللہ علیہ وسلم کی نبوت کی نشانیوں میں سے ایک ہے۔ لیکن یہ بات ذہن نشین رہنی چاہیے کہ جن احادیث میں علم کے ختم ہونے اور جہالت کے عام ہونے کو قیامت کی علامت قرار دیا گیا ہے، اس سے مراد علم شرعی ہے، جس کے ذریعے لوگ اپنے رب کو پہچانتے ہیں اور اس کی کما حقہ عبادت کرتے ہیں، نہ کہ صرف لکھائی پڑھائی۔ اور آج یہ حقیقت مشاہدہ شدہ بن چکی ہے کہ عصرِ حاضر کے منہجوں کی مروجہ کتابت و تعلیم کی وجہ سے اکثر اسلامی خاندان شریعتِ اسلامیہ سے دور اور علم شرعی سے جاہل ہو گئے ہیں، الا ما شاء اللہ۔ درج ذیل حدیث سے ہمارے اس دعوے کی تائید ہوتی ہے: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اللہ تعالی اس طرح علم کو ختم نہیں کرے گا کہ اسے لوگوں کے (سینوں سے) کھینچ لے، بلکہ وہ علما کو موت دے دے گا، اس طرح علم ناپید ہو جائے گا، جب کوئی عالم باقی نہ رہے گا تو لوگ جاہلوں کو اپنا سردار بنا لیں گے، جب ان سے سوالات کیے جائیں گے، تو وہ بغیر علم کے فتوی دیں گے، اس طرح خود بھی گمراہ ہو جائیں گے اور لوگوں کو بھی گمراہ کر دیں گے۔“ امام بخاری اور امام مسلم نے اس حدیث کو سیدنا ابن عمرو رضی اللہ عنہ، جن کی تصدیق سیدہ عائشہ رضی اللہ عنہا نے کی، سے بیان کیا ہے۔ (صحیحہ: ۲۷۶۷)"}],[3603,"سیدنا ابو امیہ جمحی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”یہ چیز علاماتِ قیامت میں سے ہے کہ حقیر و ذلیل لوگوں کے پاس علم تلاش کیا جائے گا۔“","",{"t":"علاماتِ قیامت","k":"أخرجه ابن المبارك في \"الزهد\": ۶۱، وعنه أبو عمرو الداني في \"الفتن\": ۲/ ۶۲، واللالكائي في \"شرح أصول السنة\": ۱/ ۲۳۰۔ كواكب ۵۷۶، وكذا الطبراني في \"الكبير\": وعنه الحافظ عبدالغني المقدسي في \"العلم\": ۲/ ۱۶، وابن منده في \"المعرفة\": ۱/ ۲۲۰/ ۲، وابن عبد البر في \"جامع العلم\": ۱/ ۱۵۷ - ۱۵۸، والخطيب في \"الفقيه والمتفقه\": ۲/ ۷۹\n(الصحيحة: ۶۹۵)","e":"نبی کریم صلی اللہ علیہ وسلم کی یہ پیشین گوئی اس دور میں حرف بحرف پوری ہو چکی ہے۔ بڑے بڑے تعلیمی اداروں میں ایسے ایسے لوگوں کو استفتا اور علم شرعی کے حصول کے لیے منتخب کیا جاتا ہے، جو علمی اور عملی طور پر اسلام کے بنیادی احکام سے غافل ہوتے ہیں۔ ہم نے بسیار ایسے نام نہاد علمی لوگوں کو دیکھا ہے، جو بے نماز ہیں، شیو کرتے ہیں، اسلامی آداب کے یکسر پابند نہیں ہیں، بے پردہ عورتوں میں گھل مل کر رہتے ہیں، لیکن پھر بھی وہ اسلامیات کے موضوع پر لیکچر دیتے ہیں، اپنے سہولت آمیز اور برے مزاج کے مطابق اسلام کو لچک دار بناتے ہیں، صدیوں سے اسلام کی حقیقی خدمت کرنے والوں پر کیچڑ اچھالتے ہیں اور طلبہ و عوام کی اسلام سے متعلقہ مشکلات کو حل کرتے ہیں۔ (انا لله وانا اليه راجعون)۔"}],[3604,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”یہ چیز بھی علاماتِ قیامت میں سے ہے کہ آدمی دو رکعت نماز پڑھے بغیر مسجد سے گزر جائے گا۔“","",{"t":"علاماتِ قیامت","k":"أخرجه ابن خزيمة في \"صحيحه\": ۱۳۲۶\n(الصحيحة: ۶۴۹)","e":"آج کل ہزاروں لوگوں کی ایسی مثالیں موجود ہیں، اللہ تعالی سلامت و عافیت میں رکھے۔"}],[3605,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”بد زبانی، فحش گوئی، قطع رحمی، خائن کو امین اور امانتدار کو خائن سمجھنا علاماتِ قیامت میں سے ہے۔“","",{"t":"علاماتِ قیامت","k":"أخرجه البزار: ۲۳۸\n(الصحيحة: ۲۲۳۸)"}],[3606,"قعقاع بن ابو حدرد اسلمی کی بیوی بیان کرتی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر ارشاد فرماتے ہوئے سنا: ”لوگو! جب تم قریب ہی کسی آدمی کے دھنسنے کے بارے میں سنو تو (اس کا مطلب یہ ہوگا کہ گویا) قیامت سایہ فگن ہو چکی ہے۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۶/ ۳۷۸، والحميدي: ۳۵۱\n(الصحيحة: ۱۳۵۵)"}],[3607,"سیدنا عبداللہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کے قبل (لوگوں کی) شکلیں بگڑیں گی، انھیں دھنسایا جائے گا اور ان پر سنگ باری کی جائے گی۔“","",{"t":"علاماتِ قیامت","k":"أخرجه ابن ماجه: ۴۰۵۹\n(الصحيحة: ۱۷۸۷)","e":"بیت اللہ پر چڑھائی کرنے والے لشکر کو بھی بیدا مقام پر زمین میں دھنسایا جائے گا۔ ابھی تک یہ علامات پوری نہیں ہوئیں۔"}],[3608,"سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ”قیامت سے پہلے سود، زنا اور شراب عام ہو جائے گا۔“","",{"t":"علاماتِ قیامت","k":"أخرجه الطيالسي في \"مسنده\": ۱۲۱/ ۸۹۱\n(الصحيحة: ۳۴۱۵)","e":"عصر حاضر میں کفار تو کفار، مسلمانوں میں بھی تینوں چیزیں عام ہو چکی ہیں۔"}],[3609,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت سے پہلے اندھیری رات کے ٹکڑوں کی طرح فتنے نمودار ہوں گے، آدمی بوقتِ صبح مومن ہوگا اور شام کو کافر اور بوقتِ شام مومن ہوگا اور صبح کو کافر، لوگ اپنے دین کو دنیوی ساز و سامان کے عوض فروخت کر دیں گے۔“","",{"t":"علاماتِ قیامت","k":"أخرجه الترمذي: ۳/ ۲۲۱، بشرح التحفة، وابن شيبة في \"الايمان\": ۶۴، وفي \"المصنف\": ۱۱/ ۳۹ و ۱۵/ ۴۷، والحاكم: ۴/ ۴۳۸، والفريابي في \"صفة المنافق\": ص ۶۶ من \"دفائن الكنوز\"\n(الصحيحة: ۸۱۰)","e":"جامع ترمذی کی روایت میں ان فتنوں سے پہلے پہلے عمل کرنے کا حکم دیا گیا ہے۔ ”بوقتِ صبح مومن اور شام کو کافر.....“ اس کا مفہوم یہ ہے کہ صبح کو ایمان سے متصف ہوگا اور اعمال صالحہ سے مزین گا، لیکن شام کو کفر کی دلدل میں پھنسا ہوا اور کفر یہ اعمال کرتا ہوا نظر آئے گا اور یہ معنی بھی کیا گیا ہے صبح کو اللہ تعالی کی حرام کردہ چیزوں کو حرام سمجھے گا، لیکن شام کو ان کو حلال تصور کرے گا۔ مطلب یہ ہے کہ حالات ایسا رخ اختیار کر لیں گے کہ انسان کو اپنے بدل جانے کی کوئی سمجھ نہیں آئے گی، اس معاملے میں وہ لاشعوری کا اظہار کرے گا۔ اب ایسے ہو رہا ہے کہ ایک انسان اچھا بھلا نیک پرہیزگار نظر آتا ہے، لیکن کچھ دنوں کے بعد جب اس سے ملاقات ہوتی ہے تو اس کی روحانی کیفیت بگڑ چکی ہوتی ہے اور نماز جیسے فریضے کو ترک کر چکا ہوتا ہے، کوئی سود کھانے کی وجہ سے گر چکا ہوتا تو کسی سے اچانک قتل ہو جاتا ہے، کوئی دوسرے خاندان کی بچی کی حرمتوں کو پامال کرنے کی کوشش کرتا ہے تو کوئی دوسرے کے مال کو ہڑپ کر جانے کی سوچ رہا ہوتا ہے۔ تاجروں کو کوئی شعور نہیں کہ ان کی تجارت شرعی اصولوں پر مبنی ہے یا نہیں، اپریل ۲۰۰۹ء کی بات ہے کہ ایک تاجر نے ایک شرعی قاعدے کو نظر انداز کر کے سودا کیا، اسے اس وجہ سے دو دنوں کے اندر اڑتالیس لاکھ روپے کا نقصان ہوا۔ خلاصہ کلام یہ ہے کہ لوگ دنیا میں بہت زیادہ دلچسپی لینے والے اور اس کے حریص ہوں گے اور ان کے دینی معاملات بگڑ جائیں گے۔ ملا علی قاری نے کہا: اس کا مفہوم یہ ہے کہ ایک آدمی صبح کو اصل ایمان یا کمال ایمان سے متصف ہوگا، لیکن شام کو حقیقت ایمان سے محروم ہوگا یا نعمتوں کی ناشکری کرتا ہوا یا کافروں سے مشابہت اختیار کرتا یا کافروں والے عمل کرتا ہوا نظر آئے گا۔ ایک قول یہ بھی ہے کہ صبح کو اللہ تعالی کے حرام کردہ امور کو حرام سمجھے گا، لیکن شام کو حلال سمجھنے لگے گا۔ اس جملے کا ماحصل یہ ہے کہ اس زمانے میں لوگ اپنے دین کے معاملے میں تذبذب میں ہوں گے اور ان کی ساری توجہ دنیوی امور پر مرکوز ہوگی۔ (مرقاۃ المفاتیح: ۹/ ۲۶۰)"}],[3610,"سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”علاماتِ قیامت چھ ہیں: میرا فوت ہونا، بیت المقدس کا فتح ہونا، بکری کے سینے کی بیماری کی طرح موت کا لوگوں کو دبوچنا، ہر مسلمان کے گھر کو متاثر کرنے والے فتنے کا ابھرنا، آدمی کا ہزار دینار کو خاطر میں نہ لانا (یعنی کم سمجھنا) اور روم کا غداری کرنا، وہ اسی جھنڈوں کے نیچے چلیں گے اور ہر جھنڈے کے نیچے بارہ ہزار افراد ہوں گے۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۵/ ۲۲۸، وعنه الضياء المقدسي في \"فضائل الشام\": ۲/ ۴۴/ ۲\n(الصحيحة: ۱۸۸۳)","e":"اس حدیث میں چھ علاماتِ قیامت بیان کی گئی ہیں: آپ صلی اللہ علیہ وسلم فوت ہو چکے، بیت المقدس کی فتح مکمل ہو گئی ہے، کہا جاتا ہے کہ خلافتِ فاروقی میں طاعون کی وجہ سے تین دنوں میں ستر ہزار لوگوں کا مر جانا اسی حدیث کا مصداق ہے۔ حدیث میں وہ فتنہ مراد ہے، جو سیدنا عثمان رضی اللہ عنہ کی شہادت کا سبب بنا اور پھر اس کے فتنوں کا تسلسل ابھی تک جاری ہے۔ پانچویں علامت سے مراد مال و دولت کی کثرت ہے، جو سیدنا عثمان رضی اللہ عنہ کے دور میں عظیم فتوحات کی وجہ سے پوری ہو چکی ہے، اس کے بعد سے مال و دولت میں اضافہ ہوتا رہا۔ چھٹی علامت یعنی رومیوں کا غداری کرنا: جس میں وہ سات لاکھ اور ساٹھ ہزار کے لشکر کے ساتھ آئیں گے، ابھی تک واقع نہیں ہوئی۔"}],[3611,"سیدنا حذیفہ رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم سے قیامت کے بارے میں سوال کیا گیا۔ آپ نے جواباً یہ آیت پڑھی: ”اس کا علم میرے رب ہی کے پاس ہے، اس کے وقت پر اس کو سوائے اللہ کے کوئی اور ظاہر نہ کرے گا۔“ (سورۂ اعراف: ۱۸۷) پھر فرمایا: ”البتہ میں تمھارے لیے اس کی علامتوں اور اس سے پہلے امور کی نشاندہی کر دیتا ہوں۔ اس سے پہلے فتنہ اور ہرج ہوگا۔“ صحابہ نے کہا: ہمیں فتنے کے مفہوم کا تو علم ہے، ہرج سے کیا مراد ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”یہ حبشی زبان کا لفظ ہے، اس کے معنی ”قتل“ کے ہیں، اور (قیامت سے پہلے) لوگوں میں اجنبیت پائی جائے گی، کوئی کسی کو نہیں پہچانے گا۔“","",{"t":"علاماتِ قیامت","k":"أخرجه أحمد: ۵/ ۳۸۹\n(الصحيحة: ۲۷۷۱)","e":"یہ حقیقت ہے کہ ماضی کو پرکھا جائے یا حال پر نگاہ دوڑائی جائے، ہر دور میں فتنے اور قتل بھر پور انداز میں نظر آتے ہیں، بلکہ خلفائے راشدین کے دور کے آخر سے ہی یہ سلسلہ شروع ہو گیا تھا۔ رہا مسئلہ نامانوسيت اور اجنبیت کا تو وہ تو آج عروج پر ہے، ہر آدمی نے اپنی وفا کے لیے کچھ رشتہ داروں اور چند دوسرے لوگوں کو مخصوص کر لیا ہے۔ انسان کا بحیثیتِ انسان اور مسلمان کا بحیثیتِ مسلمان احترام نہیں ہے۔"}],[3612,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم مدینہ میں تشریف لائے تو سیدنا عبد اللہ بن سلام رضی اللہ عنہ آپ صلی اللہ علیہ وسلم کے پاس آئے اور کہا: اے اللہ کے رسول! میں آپ سے تین چیزوں کے بارے میں سوال کروں گا، صرف نبی کو ان کا علم ہوتا ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”پوچھو۔“ انھوں نے کہا: قیامت کی پہلی علامت کون سی ہے؟ جنتی لوگ سب سے پہلے کون سی چیز کھائیں گے؟ اور بچے کی اپنے باپ یا ماں سے مشابہت کیسے ہوتی ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جبریل علیہ السلام نے مجھے ابھی ابھی یہ باتیں بتلائی ہیں۔“ انھوں نے کہا: یہ فرشتہ تو یہودیوں کا دشمن ہے۔ پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”قیامت کی پہلی علامت یہ ہوگی کہ مشرق سے آگ نکلے گی، وہ لوگوں کو مغرب کی طرف اکٹھا کرے گی، جنتی لوگ سب سے پہلے مچھلی کے جگر کا بڑھا ہوا حصہ کھائیں گے اور رہا مسئلہ بچے کا اپنے باپ یا ماں سے مشابہ ہونا تو جب مرد کا مادہ منویہ عورت کے پانی سے سبقت لے جاتا ہے تو بچے کی اس سے مشابہت ہو جاتی ہے اور جب عورت کا مادہ منویہ مرد کے پانی پر غالب آ جاتا ہے تو اس سے مشابہت ہو جاتی ہے۔“ سیدنا عبداللہ بن سلام نے کہا: میں گواہی دیتا ہوں کہ اللہ ہی معبودِ برحق ہے اور آپ اللہ کے رسول ہیں۔ مزید کہا: اے اللہ کے رسول! بیشک یہودی لوگ الزام تراش ہیں، جب انھیں میرے اسلام کا پتہ چلے گا تو وہ مجھ پر جھوٹے الزامات دھریں گے۔ آپ اس طرح کریں کہ ان کو بلائیں اور میرے بارے میں یوں پوچھیں: تم میں یہ ابن سلام کون اور کیسا ہے؟ آپ صلی اللہ علیہ وسلم نے ان کو بلایا اور پوچھا: ”تم میں یہ عبداللہ بن سلام کون اور کیسا ہے؟“ انھوں نے کہا: وہ بہترین فرد ہے اور بہترین باپ کا بیٹا ہے اور وہ عالم ہے اور عالم باپ کا بیٹا ہے اور وہ بہت عظیم فقیہ ہے۔ آپ صلی اللہ علیہ وسلم نے ان سے پوچھا: ”اگر وہ مسلمان ہو جائے تو کیا تم بھی مسلمان ہو جاؤ گے؟ انھوں نے کہا: اللہ تعالی اسے اس طرح کرنے سے بچائے رکھے۔ اتنے میں سیدنا عبداللہ بن سلام رضی اللہ عنہ نکلے اور کہا: میں گواہی دیتا ہوں کہ اللہ ہی معبودِ برحق ہیں اور محمد (صلی اللہ علیہ وسلم) اللہ کے رسول ہیں۔ یہ سن کر وہ کہنے لگ گئے: یہ بدترین آدمی ہے اور بدترین باپ کا بیٹا ہے اور جاہل ہے اور جاہل باپ کا بیٹا ہے۔ ابن سلام نے کہا: یہی بات ہے جس کا مجھے اندیشہ تھا۔","",{"t":"قیامت کی پہلی بڑی علامت آگ کا لوگوں کو شام میں جمع کرنا","k":"أخرجه أحمد: ۳/ ۱۰۸، وأخرجه البخاري: ۳۳۲۹، ۳۹۳۸، ۴۴۸۰، والنسائي في \"السنن الكبرى\": ۵/ ۳۳۸/ ۹۰۷۴\n(الصحيحة: ۳۴۹۳)"}],[3613,"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عنقریب روزِ قیامت سے قبل حضرموت سے آگ نکلے گی، وہ لوگوں کو جمع کرے گی۔“ صحابہ نے کہا: اے اللہ کے رسول! (ایسے وقت کا سامنا کرنے کے لیے) آپ ہمیں کیا حکم دیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”شام کو لازم پکڑنا۔“","",{"t":"قیامت کی پہلی بڑی علامت آگ کا لوگوں کو شام میں جمع کرنا","k":"أخرجه ابن أبي شيبة في \"المصنف\": ۱۵/ ۷۸\n(الصحيحة: ۲۷۶۸)","e":"”شام کو لازم پکڑنا“ کا مطلب یہ ہے کہ شام کے راستے پر چل پڑنا اور اس کے فریق کو لازم پکڑنا، کیونکہ یہ علاقہ اس وقت آگ کے پہنچنے سے سالم ہوگا اور رحمت والے فرشتے اس کی حفاظت کریں گے۔ یہ آگ اس اعتبار سے قیامت کی پہلی علامت ہے کہ اس کے بعد دنیوی امور کا وجود ختم ہو جائے گا اور اس لحاظ سے آخری نشانی ہے کہ قیامت کی جتنی نشانیاں بیان کی گئیں ہیں، ان میں سب سے آخری یہ آگ ہوگی، اس کے بعد صور پھونک دیا جائے گا۔ حافظ ابن حجر کی بحث کا خلاصہ: کل چار حشر ہوں گے، دو دنیا میں اور دو آخرت میں۔ (۱) پہلا حشر، جس کا ذکر سورۂ حشر میں ہے: ﴿هُوَ الَّذِي أَخْرَجَ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ مِنْ دِيَارِهِمْ لِأَوَّلِ الْحَشْرِ﴾۝ (سورۂ حشر: ۲) ...... ”وہی (اللہ) ہے، جس نے اہل کتاب میں سے کافروں کو ان کے گھروں سے، پہلے حشر کے وقت نکالا۔“ اس سے مراد یہودی قبیلے بنو نضیر کی جلاوطنی ہے، جو مدینہ منورہ سے نکل کر خیبر میں جا کر مقیم ہو گئے۔ بہرحال یہ حشر کی کوئی مستقل قسم نہیں ہے۔ (۲) دوسرے حشر کا ذکر اس حدیث میں کیا گیا ہے، جو قیامت کی علامت ہے، ایک روایت میں ہے کہ ”یہ آگ عدن کے انتہائی مقام سے نکلے گی اور لوگوں کو حشر کی طرف لے جائے گی۔“ جبکہ اس روایت میں ہے کہ ”یہ آگ مشرق سے نکلے گی اور لوگوں کو مغرب کی طرف اکٹھا کرے گی۔“ اس حدیث میں مغرب سے مراد شام کا علاقہ ہے۔ ان روایات میں کوئی تضاد نہیں ہے، کیونکہ جمع و تطبیق کی یہ صورت ممکن ہے کہ اس آگ کی ابتدا عدن کے انتہائی علاقے سے ہوگی، پھر یہ زمین میں پھیل جائے گی۔ (۳) مردوں کو ان کی قبروں سے اٹھا کر موقف کی طرف لے کر جانا، جیسا کہ ارشادِ باری تعالی ہے: ﴿وَحَشَرْنَاهُمْ فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا﴾۝ (۴) حساب و کتاب کے بعد لوگوں کو جنت و جہنم کی طرف لے کر جانا۔ درج ذیل بالا بحث کی مزید وضاحت درج ذیل حدیث سے ہوتی ہے: سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «سَتَكُونُ هِجْرَةٌ بَعْدَ هِجْرَةٍ فَخِيَارُ أَهْلِ الْأَرْضِ أَلْزَمُهُمْ مُهَاجَرَ إِبْرَاهِيمَ، وَيَبْقَى فِي الْأَرْضِ شِرَارُ أَهْلِهَا تَلْفِظُهُمْ أَرْضُهُمْ، تَقْذَرُهُمْ نَفْسُ اللهِ، وَتَحْشُرُهُمُ النَّارُ مَعَ الْقِرَدَةِ وَالْخَنَازِيرِ -» ...... ”ہجرت کے بعد ہجرت ہوتی رہے گی، زمین کے باسیوں میں سب سے بہتر لوگ وہ ہوں گے، جو حضرت ابراہیم علیہ السلام کے دارِ ہجرت (شام) کو اختیار کیے ہوں گے اور (قربِ قیامت کے وقت) برے لوگ ہی رہ جائیں گے۔ ان کی زمینیں انھیں نکال باہر پھینکیں گی، اللہ عزوجل بھی انھیں برا جانے گا اور آگ ان لوگوں کو بندروں اور خنزیروں کے ساتھ جمع کرے گی۔“ (ابو داود: ۲۴۸۲) آخری جملے کا معنی یہ ہے کہ آگ ان کو جمع کرے گی اور ان کو ہانکے گی، یہ لوگ آگ سے ڈر کر جانوروں کے ساتھ بھاگ جائیں گے۔"}],[3614,"سیدنا ابو جبیرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مجھے قیامت کے قریب مبعوث کیا گیا ہے۔“","",{"t":"قیامت قریب ہے","k":"رواه الدولابي في \"الكنى\": ۱/ ۲۳، وابن منده في \"المعرفة\": ۲/ ۲۳۴/ ۲، وأبو بكر أحمد الحاكم في \"الكنى\": أيضا: ۲/ ۵۶\n(الصحيحة: ۸۰۸)","e":"امام البانی رحمہ اللہ کہتے ہیں: یہ حدیث درج ذیل حدیث کے ہم معنی ہے: «بُعِثْتُ بَيْنَ يَدَيِ السَّاعَةِ -» ...... ”مجھے قیامت کے سامنے مبعوث کیا گیا ہے۔“ میں نے (ارواء الغلیل: ۱۲۶۹) میں اس کی تخریج کی ہے۔"}],[3615,"سیدنا انس بن مالک رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے سوال کیا: قیامت کب برپا ہوگی؟ اس وقت آپ صلی اللہ علیہ وسلم کے پاس محمد نامی انصاری بچہ موجود تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اسے جواب دیا: ”اگر یہ بچہ زندہ رہا تو ممکن ہے کہ اس کے بوڑھا ہونے سے پہلے قیامت قائم ہو جائے۔“ یہ حدیث سیدہ عائشہ رضی اللہ عنہا سے بھی مروی ہے۔","",{"t":"قربِ قیامت کی مثال","k":"قد ثبت من حديث أنس، وعائشة۔ (۱)۔ أما حديث أنس، فله طرق: الأولي: عن حماد بن سلمة عن ثابت البناني عن أنس بن مالك: فأخرجه مسلم: ۸/ ۲۰۹، وأحمد: ۳/ ۲۲۸، ۲۶۹ الثانية: عن قتادة عن أنس: فأخرجه البخاري: ۶۱۶۷، ومسلم، وأحمد: ۸/ ۱۹۲ الثالثة: عن الحسن عن أنس: فأخرجه أحمد: ۳/ ۲۱۳ و ۲۸۳ (۲)۔ وأما حديث عائشة؛ فأخرجه ابن أبي شيبة في \"المصنف\": ۱۵/ ۱۶۸/ ۱۹۴۰۵، ومن طريقه مسلم\n(الصحيحة: ۳۴۹۷)","e":"اس حدیث کے دو مفہوم ہیں: (۱) آپ صلی اللہ علیہ وسلم مبالغہ کے ساتھ قیامت کے قریب ہونے کو باور کرانا چاہتے ہیں، آپ صلی اللہ علیہ وسلم کا مقصد تعیین نہیں ہے، کئی دوسری احادیث سے بھی یہ مفہوم واضح ہوتا ہے۔ (۲) یہ حدیث درج ذیل حدیث کے ہم معنی ہے: آپ صلی اللہ علیہ وسلم نے فرمایا: ”جو (انسان) آج زمین پر زندہ ہیں، سو سال تک ان میں سے کوئی بھی باقی نہیں رہے گا۔“ اس حدیث کا مطلب یہ ہے کہ آپ صلی اللہ علیہ وسلم کا زمانہ ختم ہو جائے گا، واقعی ایسے ہی ہوا کہ اس وقت سے ایک صدی کے اندر اندر وہ تمام لوگ فوت ہو گئے تھے، جو اس فرمان کے وقت موجود تھے۔ حافظ ابن حجر نے کہا: محدثین کا اتفاق ہے کہ آپ صلی اللہ علیہ وسلم کی یہ پیشین گوئی پوری ہوئی اور ابو الطفیل عامر بن واثلہ رضی اللہ عنہ آخری صحابی ہیں جو ٹھیک سو برس کے بعد ۱۱۰ھ میں فوت ہوئے۔ (فتح الباری: ۲/ ۹۵) اس عنوان میں مذکورہ حدیث میں بھی آپ صلی اللہ علیہ وسلم کا مقصد یہ ہے کہ اگر یہ بچہ بوڑھا ہو کر مرا تو اس کی موت سے پہلے وہ تمام لوگ فوت ہو جائیں گے، جو اس وقت دنیا میں موجود ہیں اور ہر شخص کی قیامت اس کی موت کے بعد قائم ہو جاتی ہے۔ یہ دونوں معانی دوسری احادیث سے بھی ثابت ہوتے ہیں، اس لیے دونوں درست ہیں، کوئی ایک مراد لیا جا سکتا ہے۔"}],[3616,"سیدنا سہل بن سعد ساعدی رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مجھے اور قیامت کو ان دو انگلیوں کی طرح قریب قریب بھیجا گیا ہے۔“ پھر آپ صلی اللہ علیہ وسلم نے (تمثیل پیش کرتے ہوئے) شہادت والی اور بڑی انگلی کو آپس میں ملا دیا، نیز فرمایا: ”میری اور قیامت کی مثال مقابلے میں بھاگنے والے دو گھوڑوں کی طرح ہے (جو ایک دوسرے کے قریب ہوتے ہیں)۔“ پھر فرمایا: ”میری اور قیامت کی مثال اس آدمی کی طرح ہے، جسے لوگوں نے بطورِ جاسوس آگے بھیج دیا، اسے اندیشہ ہوا کہ دشمن تو مجھ سے پہلے پہنچ جائے گا تو اس نے کپڑا ہلایا اور کہا: تم دشمنوں کے سامنے آ گئے، تم دشمنوں کے سامنے آ گئے، میں یہ ہوں، میں یہ ہوں۔“","",{"t":"قربِ قیامت کی مثال","k":"أخرجه ابن جرير الطبري في \"تاريخه\": ۱/ ۸، والبيهقي في \"شعب الايمان\": ۷/ ۲۶۰/ ۱۰۲۳۷، وأحمد: ۵/ ۳۳۱، وأخرج البخاري: ۴۹۳۶، ۵۳۰۱، ومسلم: ۸/ ۲۰۸ وغيرهما الطرف الاول منه\n(الصحيحة: ۳۲۰)","e":"درمیانی اور شہادت والی انگلی سے اشارہ کرنے سے آپ صلی اللہ علیہ وسلم کے دو مقاصد ہو سکتے ہیں: (۱) جس طرح یہ انگلیاں ایک دوسری کے قریب اور ملی ہوئی ہیں، یہی معاملہ آپ صلی اللہ علیہ وسلم اور قیامت کا ہے، (۱) آپ صلی اللہ علیہ وسلم اور قیامت کے مابین اتنا فاصلہ رہ گیا ہے، جتنی درمیانی انگلی شہادت والی انگلی سے بڑی ہے۔ اب (۱۴۳۳ھ) سن نبوی جاری ہے، یعنی آپ صلی اللہ علیہ وسلم کی بعثت کی پندرہویں صدی جاری ہے، اور اگر شریعت میں پیش کردہ علاماتِ قیامت کو دیکھا جائے تو ابھی بھی قیامت دور ہے۔ سوال یہ ہے کہ آپ صلی اللہ علیہ وسلم نے یہ مثالیں بیان کر کے قیامت کو اتنا قریب ظاہر کیوں کیا، جبکہ قیامت تو بہت دور تھی؟ مختلف جوابات ملاحظہ فرمائیں: خلاصہ کلام یہ ہے کہ خاتم النبیین تشریف لا چکے ہیں اور اب قیامت کا معاملہ قریب آ گیا ہے۔ آپ صلی اللہ علیہ وسلم نے اس سلسلے میں مختلف مثالیں بیان کی ہیں، ان کی روشنی میں یہی مفہوم زیادہ مناسب معلوم ہوتا ہے۔ آپ صلی اللہ علیہ وسلم یہ بتلانا چاہتے ہیں کہ گزر جانے والے طویل عرصہ کی نسبت اتنا وقت باقی رہ گیا ہے، جتنی درمیانی انگلی انگشتِ شہادت سے بڑی ہے۔ (مزید تفصیل کے لیے ملاحظہ ہو: فتح الباری: ۹/ ۵۰۲، ۱۱/ ۴۲۵-۴۲۷)"}],[3617,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”لوگ تین حالتوں پر جمع ہوں گے: رغبت کرنے والے اور ڈرنے والے، دو دو آدمی ایک اونٹ پر، تین تین آدمی ایک اونٹ پر، چار چار آدمی ایک اونٹ پر اور دس دس آدمی ایک اونٹ پر سوار ہو کر آئیں گے، باقی لوگوں کو آگ اکٹھا کرے گی، جہاں وہ قیلولہ کریں گے وہ وہاں قیلولہ کرے گی، جہاں وہ رات گزاریں گے وہ وہاں رات گزارے گی، جہاں وہ صبح کریں گے وہ وہاں صبح کرے گی اور جہاں وہ شام کریں گے وہ وہاں شام کرے گی۔“","",{"t":"میدانِ حشر کی طرف جاتے وقت لوگوں کی کیفیت","k":"أخرجه البخاري: ۶۵۲۲، ومسلم: ۸/ ۱۵۷، والنسائي: ۱/ ۲۹۵، وابن حبان في \"صحيحه\": ۹/ ۲۱۷/ ۷۲۹۲، وابن أبي شيبة في \"المصنف\": ۱۳/ ۲۴۸/ ۱۶۲۴۵، وابن أبي الدنيا في \"الأهوال\": ۲۳۹/ ۲۳۵، والبيهقي في \"شعب الأيمان\": ۱/ ۳۱۸/ ۳۵۹، والطبراني في \"المعجم الأوسط\": ۶/ ۵۰/ ۵۱۰۳، والبغوي في \"التفسير\": ۵/ ۱۷۶، و \"شرح السنة\": ۱۵/ ۱۲۴/ ۴۳۱۴\n(الصحيحة: ۳۳۹۵)","e":"اس حشر کا تعلق دنیا سے ہے یا آخرت سے، نیز تین اقسام کیسے بنتی ہیں اور ہر ممکنہ صورت پر کون کون سے اعتراضات وارد ہوتے ہیں؟ تفصیل کے لیے ”فتح الباری: ۱۱/ ۳۷۱“ کا مطالعہ کریں۔"}],[3618,"سیدنا ابو امامہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”(قیامت کی بڑی بڑی علامات میں) سب سے پہلی نشانی مغرب سے سورج کا طلوع ہونا ہے۔“","",{"t":"قربِ قیامت کی سب سے بڑی نشانی مغرب سے سورج کا طلوع ہونا","k":"رواه الطبراني في \"المعجم الكبير\": ۸۰۲۲، والخطيب في \"تاريخ بغداد\": ۲/ ۱۵۶، ۵/ ۲۴، وابن حبان في \"المجروحين\": ۲/ ۲۰۴، وابن عدي في \"الكامل\": ۶/ ۲۰۴۷، وابن عساكر في \"تاريخ دمشق\": ۵/ ۳۶۵\n(الصحيحة: ۳۳۰۵)","e":"قیامت کے قائم ہونے کے وجود پر دلالت کرنے والی سب سے پہلی نشانی سورج کا مغرب سے طلوع ہونا ہوگا، تمام لوگ یہ نشانی دیکھنے کے بعد ایمان لے آئیں گے، لیکن اس نشانی کے بعد کافر کو ایمان اور فاسق و فاجر کو توبہ کوئی فائدہ نہ دے گی۔"}],[3619,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”(جب قیامت کی) تین علامتیں نمودار ہوں گی تو ﴿کسی ایسے شخص کا ایمان اس کے کام نہ آئے گا جو پہلے سے ایمان نہیں رکھتا یا اس نے اپنے ایمان میں کوئی نیک عمل نہ کیا ہو۔﴾۝ (سورۂ انعام: ۱۵۸) (وہ تین نشانیاں یہ ہیں:) سورج کا مغرب سے طلوع ہونا، دجال اور زمین کا چوپایہ۔“","",{"t":"زمین کا چوپایہ","k":"رواه مسلم: ۱/ ۹۵-۹۶، والترمذي: ۳۰۷۲، وأبو عوانة: ۱/ ۱۰۷، وابن أبي شيبة: ۵/ ۱۷۸/ ۱، وأحمد: ۲/ ۴۴۵، وأبو يعلي: ۶۱۷۰، ۶۱۷۲، وابن منده في \"الأيمان\": ۱۰۲۳، وأبو عمرو الداني في \"السنن الواردة في الفتن\": ۶۹۵، والطبراني في \"تفسيره\": ۸/ ۷۶\n(الصحيحة: ۳۶۲۰)","e":"جب بڑی نشانیوں کا ظہور ہوگا تو کافروں کا ایمان اور فاسق و فاجر کی توبہ ان کو فائدہ نہیں دے گی، حالانکہ جب لوگ سورج کو مغرب سے طلوع ہوتا ہوا دیکھیں گے تو سب ایمان لے آئیں گے، لیکن بے سود۔ ”دابّہ“ (زمین کا چوپایہ) کے بارے میں اللہ تعالی نے فرمایا: ﴿وَإِذَا وَقَعَ الْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَابَّةً مِنَ الْأَرْضِ تُكَلِّمُهُمْ أَنَّ النَّاسَ كَانُوا بِآيَاتِنَا لَا يُوقِنُونَ﴾۝ (سورۂ نمل: ۸۲) ...... ”جب ان کے اوپر عذاب کا وعدہ ثابت ہو جائے گا، ہم زمین سے ان کے لیے ایک جانور نکالیں گے، جو ان سے باتیں کرتا ہوگا کہ لوگ ہماری آیتوں پر یقین نہیں کرتے تھے۔“ صحیح مسلم کی روایت ہے کہ ”سب سے پہلی نشانی جو ظاہر ہوگی، وہ ہے سورج کا مشرق کی بجائے، مغرب سے طلوع ہونا اور چاشت کے وقت جانور کا نکلنا۔“ جانور نکلنے کی علت یہ ہے کہ لوگ اللہ تعالی کی نشانیوں یا آیتوں پر یقین نہیں رکھتے ہوں گے، اللہ تعالی اس جانور کے ذریعے اپنی نشانی دکھائے گا۔","i":"§کن علاماتِ قیامت کے بعد ایمان مفید نہیں ہوگا"}],[3620,"سیدنا ابو امامہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ایک چوپایہ نکلے گا، وہ لوگوں کی ناک پر ایک علامت لگائے گا اور وہ لمبی عمریں پائیں گے، حتی کہ ایک آدمی اونٹ خریدے گا۔ جب کوئی دوسرا اس سے پوچھے گا کہ تو نے یہ اونٹ کس سے خریدا ہے تو وہ جواب دے گا: میں نے یہ نشان زدہ لوگوں میں سے ایک آدمی سے خریدا تھا۔“","",{"t":"زمین کا چوپایہ","k":"أخرجه أحمد: ۵/ ۲۶۸، والبخاري في \"التاريخ الكبير\": ۳/ ۲/ ۱۷۲، والبغوي في \"حديث علي بن الجعد\": ۲/ ۱۷۲، وأبو نعيم في \"أخبار أصبهان\": ۲/ ۱۲۴\n(الصحيحة: ۳۲۲)"}],[3621,"سیدنا عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”علاماتِ قیامت تو ایک لڑی میں پروئے ہوئے منکوں کی طرح ہیں، اگر لڑی ٹوٹ جائے تو (منکے) لگاتار گرنا شروع ہو جاتے ہیں۔“","",{"t":"علاماتِ قیامت پے در پے آنے والی ہوں گی","k":"أخرجه الحاكم: ۴/ ۴۷۳-۴۷۴، وأحمد: ۲/ ۲۱۹\n(الصحيحة: ۱۷۶۲)"}],[3622,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”جیسے لڑی (ٹوٹنے سے) اس کے منکے پے در پے گرنا شروع ہو جاتے ہیں، ایسے ہی علاماتِ قیامت یکے بعد دیگرے تسلسل کے ساتھ نمودار ہوں گی۔“","",{"t":"علاماتِ قیامت پے در پے آنے والی ہوں گی","k":"أخرجه ابن حبان في \"صحيحه\": ۱۸۸۳، والطبراني في \"الأوسط\": ۱/ ۲۵۸/ ۴۴۳۱\n(الصحيحة: ۳۲۱۰)","e":"یعنی جب قیامت کی بڑی بڑی نشانیوں کا آغاز ہوگا تو وہ یکے بعد دیگرے مسلسل نمودار ہونا شروع ہو جائیں گی۔"}],[3623,"سعید بن ابو سعید مرسلاً بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب تم لوگ مساجد کو مزین کرو گے اور مصاحف کو خوبصورت بناؤ گے تو تم پر ہلاکت و بربادی ہوگی۔“","",{"t":"مسجد کو مزین کرنے اور مصحف کو خوبصورت بنانے پر ہلاکت","k":"قال الالباني: هذا سند مرسل حسن، وله شاهد موقوف ...... وهو وان كان موقوفا فله حكم الرفع لانه لا يقال من قبل الرأي۔ -)) تخریج: رواه ابن أبي شيبة في \"المصنف\": ۱/ ۱۰۰/ ۲ - مخطوطة الظاهرية\n(الصحيحة: ۱۳۵۱)","e":"مسجد اللہ تعالی کا گھر ہے، جب ہم اس کی تعمیر کریں گے تو گھر کے مالک سے پوچھیں گے کہ اس کا ڈیزائن کیسا ہونا چاہیے، غور کریں کہ اس سلسلے میں شریعت کے مطالبات کیا ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «اِبْنُوهُ عَرِيشًا كَعَرِيشِ مُوسَى -» یَعْنِي: مَسْجِدَ الْمَدِينَةِ - ...... ”موسی کے چھپر کی طرح اس (مسجد نبوی) کو تعمیر کر دو۔“ یہ حدیث حسن بصری، سالم بن عطیہ، زہری، اور راشد بن سعد سے مرسلاً اور سیدنا ابو درداء اور سیدنا عبادہ بن صامت رضی اللہ عنہ سے موصولاً روایت کی گئی ہے۔ (صحیحہ: ۷۱۲) مساجد کی تعمیر بلا شک و شبہ بہت بڑے اجر و ثواب کا عمل ہے، یہ عمل حصولِ جنت کا بہت بڑا سبب ہے، اس سلسلے میں اللہ تعالی تعاون کرنے والوں کو اجرِ عظیم سے نوازے (آمین)۔ بہرحال عصرِ حاضر میں اکثر مساجد کی انتظامیہ کی سوچوں کا مرکز و محور یہ بن چکا ہے کہ ان کی مسجد خوبصورت ترین ہونی چاہیے، آج کل ایک ایک مسجد پر کروڑوں روپے خرچ کیے جا رہے ہیں، جبکہ ہدایت اور ان کی آبادی کا معاملہ تعمیر نو سے پہلے والا ہی نظر آتا ہے۔ اس معاملے میں سب سے پہلے دلائل کا جائزہ لینا چاہیے۔ (۱) سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَا أُمِرْتُ بِتَشْيِيدِ الْمَسْجِدِ -» ...... ”میں (محمد صلی اللہ علیہ وسلم) کو یہ حکم نہیں دیا گیا کہ مساجد کی تزئین و آرائش کروں۔“ پھر سیدنا ابن عباس نے خود کہا: لَتُزَخْرِفُنَّهَا كَمَا زَخْرَفَتْهَا الْيَهُودُ وَالنَّصَارَى - ...... تم مساجد کو اس طرح مزین کرو گے، جیسے یہود و نصاری نے (اپنی عبادت گاہوں کو) کیا تھا۔ (ابو داود: ۴۴۸) (۲) سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «لَا تَقُومُ السَّاعَةُ حَتَّى يَتَبَاهَى النَّاسُ فِي الْمَسَاجِدِ -» «ابو داود: ۴۴۹، ابن ماجہ: ۷۳۹، نسائي: ۳۲۱۲» ...... ”اس وقت تک قیامت قائم نہیں ہوگی، جب تک کہ لوگ مساجد پر فخر نہ کرنے لگیں۔“ بڑی عجیب بات ہے کہ نبی کریم صلی اللہ علیہ وسلم کے عہدِ مبارک میں جہاد کے موقع پر کروڑہا روپوں کی مالیت کا فنڈ جمع کیا جاتا ہے، صرف سیدنا عثمان رضی اللہ عنہ نے غزوۂ تبوک کے موقع پر ایک ہزار دینار (تقریباً ۳۷۵ تولے سونا) دیا تھا اور آپ صلی اللہ علیہ وسلم نے اپنی حیاتِ مبارکہ میں جتنا مالِ غنیمت حاصل کر کے اس کو لوگوں میں تقسیم کیا، اس کا تو اندازہ بھی نہیں لگایا جا سکتا ہے، لیکن جب مسجد نبوی کی تعمیر کا وقت آتا ہے تو اس کو حضرت موسی علیہ السلام کے چھپر کا ڈیزائن دے دیا جاتا ہے۔ اللہ تعالی نے خلفائے راشدین، بالخصوص سیدنا عمر رضی اللہ عنہ کے سنہری عہدِ خلافت میں کثیر آمدنی کے انوکھے ذرائع عطا کیے، جن میں قیصر و کسری کے خزانوں کو بھی مسلمانوں پر لٹا دیا، لیکن مسجد نبوی کے عمارتی ڈیزائن میں کوئی تبدیلی نہیں لائی گئی۔ آخر راز کیا ہے؟ خیر و بھلائی اور تقوی و طہارت کا مرکز مسجد نبوی ہے، اس کے معمار محمد رسول اللہ صلی اللہ علیہ وسلم خود ہیں، مسجد حرام کے بعد اس کی فضیلت مسلّم ہے، اس میں ایک نماز کا ایک ہزار گنا زائد ثواب ملتا ہے، لیکن اس کو چھپر کی شکل میں پیش کیا جا رہا ہے۔ لہذا ہمیں بھی اپنے کیے پر غور و خوض کر کے مساجد کو آباد کرنے کی فکر کرنی چاہیے، نہ کہ ان کو خوبصورت سے خوبصورت بنانے کی اور نبی کریم صلی اللہ علیہ وسلم کی طرح شخصیتوں اور اقوام کے معماروں پر روپیہ پیسہ خرچ کر کے خدمتِ اسلام میں اپنا حصہ ڈالنا چاہیے۔ یہ بات ذہن نشین کرنا پڑے گی کہ مسجد اللہ تعالی کا گھر ہے اور اس کے نزدیک سب سے زیادہ پسندیدہ جگہ ہے، کیا یہ کہنا مناسب نہ ہوگا کہ اس کے ڈیزائن اور بناوٹ کی ترتیب کی اجازت بھی اسی سے لی جائے گی۔ ہم اپنے معاشرے کی گھروں کی پرشکوہ اور پرجلال عمارتوں سے مرعوب ہو گئے اور مساجد کا ان سے تقابل اور موازنہ کرنے لگ گئے اور پھر اپنے عمل کے حق میں دلائل تلاش کرنا شروع کر دیے۔ اس معاملے میں یہ حقیقت انتہائی حیران کن ہے کہ جو لوگ مساجد پر بے حساب رقم خرچ کرتے ہیں، اسی مسجد میں جب خطیب، امام، خادم اور تعلیمِ قرآن کے سلسلے میں بچوں کے مدرس کی تنخواہ کا مسئلہ زیر بحث آتا ہے تو انتہائی کنجوسی کا معاملہ کیا جاتا ہے اور راقم الحروف کو بلا رو رعایت یہ لکھنا پڑے گا کہ انتظامیہ کے اکثر افراد کی یہ خواہش ہوتی ہے کہ یہ لوگ فارغ البال نہ ہوں اور ان کے پنجوں میں جکڑے رہیں۔ اگر خدمتِ اسلام ہی مقصود ہے تو یہ تضاد کیوں ہے؟ دیواروں پر پردے لٹکائے جا رہے ہیں، منبر و محراب پر لاکھوں خرچ کیا جا رہا ہے، قسم قسم کی ٹائلیں لگائی جا رہی ہیں، قیمتی اور نقش و نگار والے قالین بچھائے جا رہے ہیں، وضو گاہوں اور طہارت خانوں کو مزین بنایا جا رہا ہے، مرکزی دروازوں کو دیدہ زیب بنایا جا رہا ہے، لیکن جب مساجد کی آبادی کی باری آتی ہے اور امامت، خطابت، بچوں کی تعلیم اور مسجد کی خدمت کے لیے افراد کے انتخاب کی باری آتی ہے، تو کنجوسی کا عجیب مظاہرہ کیا جاتا ہے۔ قارئین کرام! کیا آپ حیران ہوں گے کہ آج اگست ۲۰۰۹ء کی بات ہے، ایک شخص مسجد میں امامت، خطابت، ساٹھ بچوں کو قرآن کی تعلیم دینے اور مسجد کی صفائی کرنے کا ذمہ دار ہے، مسجد اس کے گھر سے پانچ گھنٹوں کے سفر پر ہے، دو تین ماہ کے بعد اس کو دو تین دن چھٹی ملتی ہے، لیکن اس کی تنخواہ پانچ ہزار روپے ہے، چار ہزار کا بندوبست ایک تنظیم کرتی ہے اور مسجد کے ”چودھری“ ایک ہزار روپیہ ماہانہ دے کر احسانِ عظیم کرتے ہیں۔ یہی لوگ جب مسجد کو مزین کرنے پر خرچ کریں گے تو کیا ان کے اقدام کو خدمتِ اسلام سمجھا جائے گا؟ (فالی اللہ المشتکی) میں اس نقطے کو نہیں سمجھ پا رہا، بہرحال دعا گو ضرور ہوں کہ اللہ تعالی ان کی خرچ کی ہوئی دولت قبول فرمائے اور ان کو مزید خلوص سے نواز دے۔"}],[3624,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب زمین میں برائی عام ہو جائے گی تو اللہ تعالی اہلِ زمین پر اپنا عذاب نازل کر دے گا۔“ سیدہ عائشہ نے کہا: کیا ان میں اللہ تعالی کی اطاعت کرنے والے بھی ہوں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جی ہاں، لیکن وہ اللہ کی رحمت کی طرف منتقل ہو جائیں گے۔“","",{"t":"برائی کا عام ہونا عذابِ الہی کا سبب ہے","k":"أخرجه أحمد: ۶/ ۴۱، وابن أبي شيبة: ۱۵/ ۴۲، والبيهقي في \"الشعب\": ۶/ ۹۸/ ۷۵۹۹م، والحاكم: ۴/ ۵۲۳\n(الصحيحة: ۳۱۵۶)"}],[3625,"سیدہ عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب زمین میں برائی عام ہو جائے گی تو اللہ تعالی اہلِ زمین پر اپنا عذاب نازل کر دے گا۔ اگر ان میں نیک لوگ ہوئے تو وہ بھی اس عذاب میں مبتلا ہو جائیں گے، پھر اللہ تعالی کی رحمت کی طرف لوٹ آئیں گے۔“","",{"t":"برائی کا عام ہونا عذابِ الہی کا سبب ہے","k":"أخرجه البيهقي في \"الشعب الأيمان\": ۲/ ۴۴۱/ ۲، والحاكم: ۴/ ۵۲۳، واحمد: ۶/ ۴۱\n(الصحيحة: ۱۳۷۲)","e":"اس میں شر و فساد کے عام ہونے کی نحوست کا بیان ہے۔ اس کا مطلب یہ ہوا کہ اگر اللہ تعالی زلزلے، سیلاب، قحط اور بیماریوں کے ذریعے اپنے بندوں کی گرفت کرتا ہے تو اس وقت لوگوں کو اپنے رویے کی نظر ثانی کرنی چاہیے۔"}],[3626,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب کوئی آدمی یہ کہے کہ لوگ تباہ ہو گئے (کوئی حال نہیں رہا لوگوں کا)، تو وہ ان میں سب سے زیادہ تباہ ہونے والا ہوگا۔“","",{"t":"دوسروں کی بجائے اپنی فکر زیادہ کرنی چاہیے","k":"أخرجه مالك في \"الموطأ\": ۳/ ۱۴۸، ومسلم: ۸/ ۳۶، والبخاري في \"الأدب المفرد\": ۷۵۹، وأبو داود: ۴۹۸۳، وابن حبان في \"صحيحه\": ۵۷۳۲، وأحمد: ۲/ ۲۷۲، ۳۴۲، ۴۶۵، ۵۱۷، وأبو نعيم في \"الحلية\": ۷/ ۱۴۱ و \"أخبار أصبهان\": ۱/ ۱۵۰، ۲۷۶، ۲/ ۳۶۴، والبغوي في \"شرح السنة\": ۱۳/ ۱۴۴\n(الصحيحة: ۳۰۷۴)","e":"امام نووی نے کہا: یہ کہنا کہ لوگ تباہ ہو گئے ہیں، اس شخص کے لیے منع ہے، جو اپنے آپ کو اچھا سمجھے، لوگوں کو حقیر گردانے اور ان پر اپنے آپ کو برتر خیال کرے۔ لیکن جو شخص یہ دیکھتا ہے کہ لوگوں میں دینداری کم ہو گئی ہے اور اس پر اظہارِ افسوس کرتے ہوئے دینی غیرت و حمیت کی وجہ سے یہ الفاظ اس کی زبان پر آ جائیں تو کوئی حرج نہیں ہے۔ امام مالک بن انس، امام حمیدی اور امام خطابی جیسے علما نے اس حدیث کی یہی تفصیل بیان کی ہے۔ (ریاض الصالحین) ہمارے معاشرے میں اکثر لوگوں کا یہ حال ہے کہ وہ اپنے آپ کو اچھا سمجھتے ہیں اور دوسروں کو نہ صرف حقیر گردانتے ہیں، بلکہ ان کے عیوب تلاش کرنے اور ان کی نیکیوں کو کوئی دوسرا رخ دینے میں لگے رہتے ہیں۔ ایک دن میں ایک بے دین سے آدمی کے پاس بیٹھا ہوا تھا، ایک اچھے خاصے دین دار شخص کا تذکرہ ہونے لگا، میں نے اس کی شرعی صفات کی وجہ سے اس کی تعریف کرنا چاہیے، لیکن جناب نے صرف اس بنا پر اس کو انتہائی برا کہا کہ اس نے اسے وعدے کے مطابق قرضہ واپس نہیں کیا تھا، جبکہ وہ بزعمِ خود اپنے آپ کو دین دار ٹھہرا رہا تھا، حالانکہ پرلے درجے کا بدعمل شخص تھا، آج کل اکثریت کا یہی رویہ ہے۔"}],[3627,"ابو بردہ اپنے باپ ابو موسی اشعری رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب قیامت کا دن ہوگا، تو ہر مومن کے پاس ایک فرشتہ کافر کو لے کر آئے گا اور اسے کہے گا: اے مومن! لیجئے یہ کافر، یہ جہنم سے تیرا فدیہ ہے۔“","",{"t":"کفار، مومنوں کا جہنم سے فدیہ ہیں","k":"أخرجه ابن عساكر: ۱۸/ ۱۴۳/ ۲، والحديث اخرجه مسلم: ۸/ ۱۰۴، واحمد: ۴/ ۳۹۱، ۴۰۲، ۴۰۷\n(الصحيحة: ۱۳۸۱)"}],[3628,"سیدنا مقداد رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب قیامت کا دن ہوگا تو سورج کو لوگوں کے اتنا قریب کر دیا جائے گا کہ وہ ایک یا دو میلوں کے فاصلے پر آ جائے گا۔ سورج (کی تپش) ان کو پگھلا دے گی، وہ اپنے اعمال کے بقدر پسینے میں شرابور ہوں گے، کسی کا پسینہ ایڑیوں تک ہوگا، کسی کا گھٹنوں تک، کسی کا کمر تک اور کسی کا منہ تک آ جائے گا۔“ پھر آپ صلی اللہ علیہ وسلم نے اپنے منہ کی طرف اشارہ کیا یعنی اس کے منہ تک آ جائے گا۔","",{"t":"میدانِ حشر میں سورج کا قریب ہونا اور لوگوں کا پسینے میں شرابور ہونا","k":"أخرجه مسلم: ۲۸۶۴، والترمذي: ۲۴۲۳، وأحمد: ۶/ ۳\n(الصحيحة: ۱۳۸۲)","e":"اللہ تعالی عافیت میں رکھے، ہر مسلمان کو آخرت کی فکر کرنی چاہیے، بہرحال ایسے خوش نصیب لوگ حشر کے میدان میں موجود ہوں گے، جن کو اللہ تعالی کے عرش کا سایہ نصیب ہوگا۔ اللہم اجعلنا منہم۔"}],[3629,"سیدنا ابو موسی رضی اللہ عنہ سے روایت ہے، نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”فتنوں میں اپنی کمانیں توڑ دینا اور ان کی تانتیں کاٹ دینا، اپنے گھروں کے اندر ہی رہنا اور حضرت آدم (علیہ السلام) کے دو بیٹوں میں سے نیک بیٹے کی طرح (جنگ و جدل سے دست کش) ہو جانا۔“","",{"t":"زمانۂ فتن کے احکام","k":"رواه الترمذي: ۳/ ۲۲۲ - تحفة، والبيهقي في \"الشعب\": ۲/ ۱۱۳/ ۲، وابن عساكر: ۱۷/ ۴۹۱/ ۱\n(الصحيحة: ۱۵۲۴)"}],[3630,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”عبداللہ بن عمرو! اس وقت تیرا کیا بنے گا جب تو گھٹیا اور ادنی درجے کے لوگوں میں باقی رہ جائے گا، ان کے عہد و پیمان اور امانت و دیانت میں کھوٹ پیدا ہو جائے گی، وہ اختلاف و افتراق میں پڑ جائیں گے اور وہ اس طرح خلط ملط ہو جائیں گے۔“ پھر آپ صلی اللہ علیہ وسلم نے اشارہ کرتے ہوئے اپنے ہاتھوں کی انگلیوں کو ایک دوسرے میں داخل کر دیا۔ میں نے کہا: اے اللہ کے رسول! آپ مجھے ایسے حالات میں کیا حکم دیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اپنی فکر کرنا اور عوام الناس (کے معاملات میں) نہ پڑنا۔“","",{"t":"زمانۂ فتن کے احکام","k":"أخرجه الدولابي في \"الكنى\": ۲/ ۳۵، وابن حبان في \"صحيحه\": ۱۸۴۹، وأبو عمرو الداني في \"السنن الواردة\": ۲/ ۱۶، وابن السماك في \"الأول من الرابع من حديثه\": ۱۰۸\n(الصحيحة: ۲۰۶)"}],[3631,"عمرو بن وابصہ اسدی اپنے باپ سے روایت کرتے ہیں، وہ کہتے ہیں: میں کوفہ میں اپنے گھر میں تھا، اچانک مجھے گھر کے دروازے سے آواز آئی: السلام علیکم، میں اندر آ جاؤں؟ میں نے کہا: وعلیکم السلام، آ جاؤ۔ جب وہ اندر آیا تو کیا دیکھتا ہوں کہ وہ سیدنا عبداللہ بن مسعود رضی اللہ عنہ تھے۔ میں نے کہا: ابو عبدالرحمن! آیا یہ ملاقات کا وقت ہے؟ یہ سخت دوپہر کا وقت تھا۔ انھوں نے کہا: دن نہیں گزر رہا تھا، مجھے خیال آیا کہ چلو گفتگو کر لیتے ہیں۔ پھر انھوں نے ایک دوسرے کو رسول اللہ صلی اللہ علیہ وسلم کی احادیث بیان کرنا شروع کر دیں، انھوں نے یہ حدیث بھی بیان کی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”فتنوں کا (ایسا زمانہ شروع ہوگا کہ) اس میں سونے والا لیٹنے والے سے بہتر ہوگا، لیٹنے والا بیٹھنے والے سے بہتر ہوگا، بیٹھنے والا کھڑا ہونے والے سے بہتر ہوگا، کھڑا ہونے والا چلنے والے سے بہتر ہوگا، چلنے والا سوار سے بہتر ہوگا اور سوار دوڑنے والے سے بہتر ہوگا۔ ان کے سارے کے سارے مقتولین جہنم میں جائیں گے۔“ میں نے کہا: اے اللہ کے رسول! ایسے کب ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”قتل و غارت گری کے ایام میں ایسے ہوگا۔“ میں نے کہا: قتل کے ایام کب ہوں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جب آدمی اپنے ہم نشین سے خوفزدہ ہوگا۔“ میں نے کہا: اگر میں ایسا زمانہ پا لوں تو آپ میرے حق میں کیا حکم ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اپنے آپ کو اور اپنے ہاتھ کو قابو میں رکھنا اور اپنے گھر کے اندر رہنا۔“ میں نے کہا: اے اللہ کے رسول! اگر کوئی (فتنے باز) میرے گھر کے اندر بھی گھس آیا تو مجھے کیا کرنا ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تو اپنے کمرے میں داخل ہو جانا۔“ میں نے کہا: اے اللہ کے رسول! اگر میرے کمرے میں گھس آئے تو؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اپنی سجدہ گاہ میں داخل ہو جانا اور اس طرح کر لینا، پھر آپ صلی اللہ علیہ وسلم نے دائیں ہاتھ سے کلائی کو پکڑ لیا، اور کہنا: میرا رب اللہ ہے، (اسی حالت پر برقرار رہنا) حتی کہ تو مر جائے۔“","",{"t":"زمانۂ فتن کے احکام","k":"رواه عبدالرزاق في \"المصنف\": ۱۱/ ۳۵۰/ ۲۰۷۲۷، ومن طريقه: أحمد: ۱/ ۴۴۸، والحاكم: ۴/ ۴۲۶\n(الصحيحة: ۳۲۵۴)","e":"”سارے کے سارے مقتولین جہنم میں جائیں گے“ اس کو مسلمانوں کے مابین ہونے والی ان لڑائیوں پر محمول کیا جائے گا، جن کی دونوں طرف سے بنیاد عصبییت، حمیت اور جاہلیت پر ہوگی اور ان میں کوئی شرعی سبب نہیں ہوگا۔"}],[3632,"سُبیع کہتے ہیں: لوگوں نے مجھے کچھ جانور خریدنے کے لیے پانی کے گھاٹ سے کوفہ کی طرف بھیجا، ہم ایک کوڑا خانے کے پاس سے گزرے، ہم نے ایک آدمی دیکھا، اس کے اردا گرد لوگ جمع تھے، میرا دوست جانوروں کی طرف چلا گیا اور میں اس آدمی کے پاس آ گیا، میں کیا دیکھتا ہوں کہ وہ سیدنا حذیفہ رضی اللہ عنہ تھے، وہ کہہ رہے تھے: صحابہ کرام، رسول اللہ صلی اللہ علیہ وسلم سے خیر کے بارے میں پوچھتے تھے اور میں شر کے بارے میں سوال کرتا تھا۔ میں نے کہا: اے اللہ کے رسول! کیا اس خیر (یعنی اسلام) کے بعد پھر وہی شر منظر عام پر آئے گی جو اس سے پہلے تھی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جی ہاں۔“ میں نے کہا: اس سے بچنے کا کیا طریقہ ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تلوار۔“ میں نے کہا: پھر کیا ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”لیکن باطن لڑائی ہوگی اور ظاہری صلح ہوگی، اس کے بعد ضلالت و گمراہی کی طرف پکارنے والے منظر عام پر آئیں گے، اگر ان دنوں میں تجھے کوئی خلیفہ نظر آ جائے تو اسے لازم پکڑ لینا، اگر چہ وہ تیرے جسم کو اذیت پہنچائے اور تیرا مال سلب کر لے اور اگر کوئی خلیفہ نظر نہ آئے تو زمین (کے کسی گوشہ کی طرف) بھاگ جانا، اگرچہ تجھے اس حال میں موت آ جائے کہ تو درخت کے تنے کے ساتھ چمٹا ہوا ہو۔“ میں نے کہا: پھر کیا ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”پھر دجال نمودار ہوگا............۔“","",{"t":"زمانۂ فتن کے احکام","k":"أخرجه أبو داود: ۴۲۴۷، وأحمد: ۵/ ۴۰۳\n(الصحيحة: ۱۷۹۱)"}],[3633,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ”جب تم پر اندھیری رات کے ٹکڑوں کی طرح فتنے ٹوٹ پڑیں گے تو ان سے زیادہ نجات حاصل کرنے والے (دو قسم کے لوگ ہوں گے): (۱) (پہاڑوں کی) بلند و بالا چوٹیوں پر نکل جانے والا آدمی جو بکریوں کے دودھ کو خوراک بنائے گا اور (۲) وہ آدمی جو شاہراہِ حیات سے ہٹ کر اپنے گھوڑے کی لگام تھام کر (کسی سرحد پر فروکش ہو کر) اپنے تلوار کے مالِ غنیمت کے ذریعے روزی کمائے گا۔“","",{"t":"زمانۂ فتن کے احکام","k":"أخرجه الحاكم: ۲/ ۹۲-۹۳\n(الصحيحة: ۱۴۷۸)"}],[3634,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ”اندھیری رات کے ٹکڑوں کی طرح تمھیں فتنے ڈھانپ لیں گے، نجات پانے والا آدمی وہ ہوگا جو (پہاڑوں وغیرہ کی) بلند و بالا چوٹیوں پر فروکش ہو کر بکریوں کے دودھ پر گزارا کرتا رہے گا یا وہ آدمی جو اپنے گھوڑے کی لگام تھام کر شاہراہِ حیات سے پرے (مصروفِ جہاد ہوگا) اور اپنی تلوار (کی غنیمتوں) سے کھائے گا۔“","",{"t":"زمانۂ فتن کے احکام","k":"أخرجه الحاكم: ۴/ ۵۱۴\n(الصحيحة: ۱۹۸۸)","e":"اسلام ایسا جامع مذہب ہے کہ حالات جیسے بھی ہوں، اس میں ان سے نبٹنے کی ہدایات موجود ہیں، ضروری امر یہ ہے کہ مسلمانوں کے پاس اتنی بصیرت ہو کہ وہ انجام و عاقبت پر نگاہ ڈال کر اپنے لیے کوئی لائحہ عمل تیار کر سکیں۔ اگر سکت ہو تو برائی کو ہاتھ سے دبایا جائے، نہیں تو زبان سے اسے روکنے کی کوشش کی جائے، وگرنہ دل میں ہی اس کو برا سمجھ لیا جائے، لیکن اگر کسی معاشرے میں اتنا بگاڑ پیدا ہو گیا ہو کہ وہاں کے مسلمانوں کو فتنے کا ڈر ہو اور حرام و مشتبہ امور میں مبتلا ہونے کا اندیشہ ہو، تو ایسے حالات میں اللہ تعالی عبادت و اطاعت کے لیے گوشہ نشینی اختیار کرنا افضل لوگوں کا کام ہے۔ جیسا کہ سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «يُوشِكُ أَنْ يَكُونَ خَيْرَ مَالِ الْمُسْلِمِ غَنَمٌ يَتْبَعُ بِهَا شَعَفَ الْجِبَالِ وَمَوَاقِعَ الْقَطْرِ، يَفِرُّ بِدِينِهِ مِنَ الْفِتَنِ -» ...... ”عنقریب ایسا (پر فتن) وقت آئے گا کہ مسلمان کا بہترین مال وہ بکریاں ہوں گی جن کو لے کر وہ پہاڑوں کی چوٹیوں اور بارش کے گرنے کے مقامات (یعنی جنگلوں میں) چلا جائے گا، اس طرح وہ اپنے دین کو فتنوں سے بچا سکے گا۔“ (صحیح بخاری: ۱۹) یاد رہے کہ عام حالات میں اسلام رہبانیت کی اجازت نہیں دیتا کہ مسلمان دنیا سے بھاگ کر جنگلوں اور صحراؤں میں نکل جائے، مسلمان کا کمال اور امتیاز اس میں ہے کہ وہ اپنے جیسے انسانوں میں رہ کر حقوق اللہ اور حقوق العباد کو احسن انداز میں ادا کرے، حق و باطل کی کشمکش اور معرکہ آرائی میں حق کو سر بلند کرنے اور باطل کو نیست و نابود کرنے کے لیے جدوجہد کرے اور اس منہج میں صبر آزما مشکلات کو خندہ پیشانی کے ساتھ برداشت کرے۔ ان روایات سے یہ بھی ثابت ہوا کہ یہ ضروری نہیں کہ جب بھی کسی انسان کی توہین کی جائے تو وہ اپنا دفاع کرے، اسے سوچنا یہ چاہیے کہ اگر وہ جوابی کاروائی کرے تو آیا کوئی بڑا فساد تو لازم نہیں آئے گا، اگر ایسی صورت ہے تو اسے صبر کرنا چاہیے، وگرنہ ہم نے دیکھا کہ معمولی بات سے جھگڑا شروع ہوا، پھر ایک دوسرے کے مقابلے میں اتنے افراد کو قتل کیا گیا کہ خاندانوں کے خاندان اجڑ گئے اور ان کی عورتوں کی حرمتوں کو پامال کر دیا گیا۔ کیا یہ بہتر نہیں تھا کہ شروع میں تھوڑی سی بے عزتی برداشت کر لی جاتی۔ مومن حکیم ہوتا ہے، کبھی بھی اس کا فیصلہ حکمت سے خالی نہیں ہونا چاہیے۔ اس موقع پر مجھے یہ واقعہ بیان کر دینا چاہیے کہ ہم جھنگ سے ٹوبہ ٹیک سنگھ کی طرف ہائی ایس پر سفر کر رہے تھے، آگے سے ایک کار آ رہی تھی، سڑک کی حالت خراب ہونے کی وجہ سے راستے کا کوئی مسئلہ بنا اور دونوں ڈرائیور ایک دوسرے سے خفا ہونے لگے۔ ہائی ایس کا ڈرائیور زیادہ جذباتی اور جاہل تھا، وہ خوب گالی گلوچ کرتا ہوا اپنی گاڑی سے اترا اور زدوکوب کرنے کے لیے دوسرے ڈرائیور کی طرف لپکا، لیکن وہ اپنی کار میں بیٹھا اور اس کے پہنچنے سے پہلے نکل گیا۔ ہائی ایس میں سوار مسافر بیک زبان ہو کر بولے کہ نکلنے والا جیت گیا ہے۔ کتنا حکیم تھا وہ آدمی! جو اس جنگل میں ہونے والی غیر متوقع لڑائی سے فرار اختیار کر گیا، کسی کو کیا پتہ کہ وہ کون تھا اور کہاں گیا، اس لیے بے عزتی سے بھی بچ گیا۔"}],[3635,"سیدنا انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”لوگوں پر ایسا زمانہ بھی آئے گا کہ اپنے دین پر صبر کرنے والا دہکتے ہوئے انگارے کو مٹھی میں بند کرنے والے کے مترادف ہوگا۔“","",{"t":"بعض زمانوں میں صبر کرنا مشکل عمل ہوگا","k":"رواه الترمذي: ۲/ ۴۲، وابن عدي في \"الكامل\": ۵/ ۵۵، وابن بطة في \"الابانة\": ۱/ ۱۷۳/ ۲\n(الصحيحة: ۹۵۷)","e":"امتِ مسلمہ کا ماضی بھی اس حدیث کا مصداق بنا رہا، اب بھی بعض لوگ آزمائشوں میں مبتلا ہیں اور مستقبل میں بھی یقیناً بعض صورتیں اس حدیث کا مصداق بنیں گی۔ اس حدیث سے یہ بھی معلوم ہوا کہ ضروری نہیں کہ زمانۂ فتن میں مسلمان اپنے آپ کو مجبور سمجھ کر لوگوں کی موافقت اختیار کرنا شروع کر دے، بلکہ اسے سب سے پہلے صبر کا دامن تھامنے کی ہر ممکن کوشش کرنی چاہیے۔"}],[3636,"سیدہ میمونہ رضی اللہ عنہا کہتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ایک دن فرمایا: ”جب دین میں فساد آ جائے گی، خونریزی ہوگی، بناؤ سنگھار عام ہوگا، بڑی بڑی عمارتیں تعمیر کی جائیں گی، رغبت بڑھ جائے، بھائیوں میں اختلاف پڑ جائے گا اور بیتِ عتیق جلا دیا جائے گا تو تمھارا کیا بنے گا؟“","",{"t":"فتنوں کی مختلف صورتیں اور آپ صلی اللہ علیہ وسلم کا اظہارِ افسوس","k":"أخرجه ابن شيبة في \"المصنف\": ۱۵/ ۴۷، وعنه الطبراني في \"الكبير\": ۲۴/ ۲۶/ ۶۷، وأحمد في \"المسند\": ۶/ ۳۳۳\n(الصحيحة: ۲۷۴۴)","e":"امام البانی رحمہ اللہ بیان کرتے ہیں: ابن اثیر نے کہا: ”الرغبۃ“ کے معانی پاکدامنی کے کم ہو جانے اور سوال کے زیادہ ہو جانے کے ہیں۔ اگر دورِ حاضر میں قتل و غارت گری کی کثرت، زیب و زینت کے ظہور اور بڑی بڑی عمارتوں کے سلسلے پر نگاہ ڈالی جائے تو یہ حدیث آپ صلی اللہ علیہ وسلم کا عملی معجزہ نظر آتی ہے۔ عمارتوں، لباسوں، تجارتی مرکزوں، نوجوانوں کی قمیصوں اور مرد و زن کے جوتوں پر سجاوٹ و آرائش کے عجیب و غریب ڈیزائن نظر آتے ہیں۔ اللہ تعالی اس ہستی پر درود و سلام نازل فرمائے، جن کا یہ وصف بیان کیا گیا ہے: ﴿وَمَا يَنْطِقُ عَنِ الْهَوَى إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى﴾۝ (سورۂ نجم: ۳، ۴) ...... ”اور نہ وہ اپنی خواہش سے کوئی بات کہتے ہیں، وہ تو صرف وہی ہے جو اتاری جاتی ہے۔“ (صحیحہ: ۲۷۴۴)"}],[3637,"عدیسہ بنت اہبان کہتی ہیں کہ جب سیدنا علی رضی اللہ عنہ بصرہ کی طرف سے آئے تو میرے باپ کے پاس آئے اور کہا: ابو مسلم! کیا تم ان لوگوں کے خلاف میری مدد کرو گے؟ انھوں نے کہا: کیوں نہیں، پھر اپنی لونڈی کو بلایا اور کہا: لونڈی! میری تلوار نکال لاؤ۔ وہ تلوار لے آئیں۔ انھوں نے ایک بالشت کے بقدر تلوار (میان سے) نکالی، وہ لکڑی کی تلوار تھی۔ پھر کہا: میرے دوست اور تیری چچا زاد (محمد رسول اللہ صلی اللہ علیہ وسلم) نے مجھے یہ وصیت کی تھی: ”جب مسلمانوں میں فتنے ابھر آئیں گے تو لکڑی کی تلوار بنا لینا۔“ اب اگر تم چاہتے ہو تو میں (یہ لکڑی کی تلوار لے کر) تمھارے ساتھ آ جاتا ہوں۔ سیدنا علی رضی اللہ عنہ نے کہا: مجھے تیری اور تیری تلوار کی کوئی ضرورت نہیں ہے۔","",{"t":"زمانۂ فتن میں لکڑی کی تلوار کا اہتمام کرنے کی وصیت","k":"أخرجه الترمذي: رقم ۲۲۰۴، وابن ماجه: ۳۹۶۰ واللفظ له، وأحمد: ۵/ ۶۹، ۶/ ۳۹۳، والطبراني في \"الكبير\": ۱/ ۴۴\n(الصحيحة: ۱۳۸۰)","e":"سیدنا علی رضی اللہ عنہ کی خلافت میں مسلمان دو گروہوں میں بٹ گئے، پھر ان دو میں لڑائیاں بھی لڑی گئیں، کئی صحابہ بھی شریک ہوئے، لیکن بعض صحابہ ان کو فتنہ سمجھ کر ان میں شرکت کرنے سے باز رہے، حالانکہ وہ سیدنا علی رضی اللہ عنہ سے محبت کرنے والے، ان کو باقیوں پر مقدم سمجھنے والے اور اپنے زمانہ میں ان کو خلافت کے زیادہ مستحق سمجھنے والے تھے، مثلا: سیدنا عبداللہ بن عمر، سیدنا اسامہ بن زید اور سیدنا سعد بن وقاص رضی اللہ عنہم وغیرہ۔ ان لوگوں کے پاس ایسے مرفوع نصوص تھے، جن میں یہ رہنمائی کی گئی تھی کہ اس قسم کے جنگ و قتال سے اجتناب کرنا اس میں شرکت کرنے سے بہتر ہے، اگر چہ دونوں گروہوں کا اجتہاد یہ تھا کہ وہ حق پر ہیں۔ صحابہ کے فریقین کے بارے میں کیا کہنا چاہیے؟ اس عنوان کا مطالعہ کریں: ”سیدنا علی رضی اللہ عنہ حق پر تھے، مشاجراتِ صحابہ کے بارے میں متاخرین میں کیا کہنا چاہیے؟“"}],[3638,"علیم کہتے ہیں: میں عابس غفاری کے پاس چھت پر بیٹھا ہوا تھا، انھوں نے کچھ لوگوں کو طاعون میں مبتلا دیکھا اور کہا: یہ لوگ طاعون میں مبتلا کیوں ہیں؟ اے طاعون! مجھ پر طاری ہو جا۔ (انھوں نے یہ بات دو دفعہ کی)۔ ان کے چچا زاد، جو صحابی تھے، نے انھیں کہا: آپ موت کی تمنا کیوں کرتے ہیں، حالانکہ آپ نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”کوئی بھی موت کی تمنا نہ کرے، کیونکہ موت اعمال کے سلسلے کو منقطع کر دینے والی چیز ہے، کسی کو (موت کے بعد اللہ کو) راضی کرنے کے لیے دوبارہ موقع نہیں دیا جائے گا۔“ نیز فرمایا: ”ان چھ امور سے پہلے پہلے اعمال کر لو: بیوقوفوں کی حکومت، پولیس کی کثرت، قطع رحمی، عہدوں اور فیصلوں کی خرید و فروخت، انسانی خون کی ارزانی، کیف و سرور والے لوگ جو قرآن مجید کو سریلی آواز میں پڑھنے کا اہتمام کریں گے، وہ ایسے آدمی کو مقدم کریں گے جو فقیہ نہ ہوگا نہ عالم، صرف وجہ یہ ہوگی کہ وہ انھیں قرآن مجید گا کر سنائے گا۔“","",{"t":"فتنوں کے ظہور سے پہلے عمل کر لینے کی تلقین","k":"أخرجه أحمد: ۳/ ۴۹۴، وأبو عبيد في \"فضائل القرآن\": ۳/ ۲، وأبو غرزة الحافظ في \"مسند عابس\": ۲/ ۱، وابن أبي الدنيا في \"العقوبات\": ۷۸/ ۱، والطبراني في \"الكبير\": ۱۸/ ۳۶/ ۶۱، ورواه الطبراني و ابن شاهين\n(الصحيحة: ۹۷۹)","e":"قارئین کرام! شاید آپ بھی اس حقیقت سے متفق ہوں کہ ہمارے دور میں یہ چھ چیزیں بدرجۂ اتم موجود ہیں، آج ۱۴۳۰ھ کے شعبان کی سترہ تاریخ ہے، ہر مسجد کی انتظامیہ تراویح کے لیے حافظینِ قرآن کی تلاش میں ہے، کسی کی یہ ترجیح نظر نہیں آتی کہ قاری صاحب فقاہت، علم شرعی، تقوی و طہارت سے متصف ہوں، ہر ایک کی یہی رٹ ہے کہ سریلی آواز ہو، آیات کو گا کر پڑھتا ہو اور رفتار میں بھی تیزی ہو، تاکہ لوگ ان کی مسجد کی طرف کھنچے چلے آئیں۔ آج کل قرا حضرات کی آزمائش شروع ہیں، وہ ایک مسجد میں جا کر جہری نماز پڑھا کر انٹرویو دے رہے ہیں، سلام پھیرتے ہی مسجد کے چند چودھری صاحبان فیصلہ دے دیتے ہیں کہ مزہ نہیں آیا، کسی اور کو بلاتے ہیں۔ آخر کیا وجہ ہے کہ آپ صلی اللہ علیہ وسلم نے ہی تلاوتِ قرآن میں حسن پیدا کرنے کا حکم دیا اور آپ صلی اللہ علیہ وسلم ہی اس حدیث میں اس قسم کے لوگوں کا رڈ بھی کر رہے ہیں۔ اصل وجہ یہ ہے کہ امام میں تقوی و پارسائی، علم و فقاہت اور خوفِ خدا جیسی صفات پائی جانی چاہیں اور عوام الناس کو فہمِ قرآن پر توجہ کرنی چاہیے، ان امور کے ساتھ ساتھ آواز میں حسن پیدا کرنے کی کوشش کرنی چاہیے۔"}],[3639,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”ان چھ امور سے پہلے پہلے اعمال کر لو: مغرب سے سورج کا طلوع ہونا، دجال، دھواں، زمین کا چوپایہ، موت اور عوام الناس کا معاملہ (یعنی ایسا فتنہ جو لوگوں کا گھیراؤ کر لے گا، یا وہ معاملہ جس میں عوام خود مختار بن جائیں گے)۔“","",{"t":"فتنوں کے ظہور سے پہلے عمل کر لینے کی تلقین","k":"أخرجه مسلم: ۸/ ۲۰۸، وابن حبان: ۸/ ۲۷۹/ ۶۷۵۲، وأحمد: ۲/ ۳۲۴، ۴۰۷\n(الصحيحة: ۷۵۹)","e":"«خویصۃ احدکم» کے تین معانی ہے: موت، ہر شخص سے متعلقہ مخصوص لڑائی، ہر شخص کے جان و مال سے متعلقہ مصروفیات۔ جب بندہ ان تین امور میں کسی ایک میں پھنس جاتا ہے تو وہ اعمالِ صالحہ کی روٹین برقرار نہیں رکھ سکتا، بالخصوص موت۔ دجال، جہتِ مغرب سے طلوعِ آفتاب اور چوپایہ، ان تین علامتوں کے ظہور کے بعد نہ تو ایمان قبول کرنا مفید ثابت ہوگا اور نہ فاسق و فاجر کو اس کی توبہ فائدہ دے گی۔ دھویں کے تعین کے بارے میں دو اقوال ہیں: (۱) قیامت کے قریب آنے کی علامت ہے، ابھی تک ظہور پذیر نہیں ہوئی، اس کی ہیئت و حقیقت کا علم اللہ تعالی کو ہے۔ (۲) نبی کریم صلی اللہ علیہ وسلم کے دور میں یہ نشانی ظاہر ہو چکی ہے۔ نبی کریم صلی اللہ علیہ وسلم نے اہل مکہ کے معاندانہ رویے سے تنگ آ کر ان کے لیے قحط سالی کی بددعا کی، نتیجتاً ان پر قحط کا عذاب نازل کر دیا گیا، حتی کہ وہ ہڈیاں، کھالیں اور مردار وغیرہ کھاتے تھے، جب آسمان کی طرف دیکھتے تو بھوک اور کمزوری کی شدت کی وجہ سے انھیں دھواں سا نظر آتا تھا۔ زمین کا یہ چوپایہ قریب قیامت کی علامت ہے، یہ لوگوں سے کلام کرے گے۔"}],[3640,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اندھیری رات کی طرح چھا جانے والے فتنوں سے پہلے پہلے عمل کر لو، اُس وقت آدمی بوقتِ صبح مومن ہوگا اور شام کو کافر یا بوقتِ شام مومن ہوگا اور صبح کو کافر، وہ اپنے دین کو دنیوی ساز و سامان کے بدلے فروخت کر دے گا۔“","",{"t":"فتنوں کے ظہور سے پہلے عمل کر لینے کی تلقین","k":"أخرجه مسلم: ۱/ ۷۶، والترمذي: ۳/ ۳۲۰-۳۲۱ بشرح التحفة، وصححه، وكذا ابن حبان: ۱۸۶۸، وأحمد: ۲/ ۳۰۴، والفريابي في \"صفة المنافق\": ص۶۵ من \"دفائن الكنوز\"، وأبو يعلي: ۱۱/ ۳۹۶/ ۶۵۱۵\n(الصحيحة: ۷۵۸)"}],[3641,"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اندھیری رات کے ٹکڑوں کی طرح فتنے میری امت کو ڈھانپ لیں گے۔ بندہ بوقتِ صبح مومن ہوگا اور شام کو کافر اور بوقتِ شام مومن ہوگا اور صبح کو کافر۔ لوگ دنیوی معمولی ساز و سامان کے عوض اپنے دین کو فروخت کر دیں گے۔“","",{"t":"فتنوں کے ظہور سے پہلے عمل کر لینے کی تلقین","k":"أخرجه الحاكم: ۴/ ۴۳۸\n(الصحيحة: ۱۲۶۷)","e":"ان تمام احادیث میں آپ صلی اللہ علیہ وسلم یہ حکم دینا چاہتے ہیں کہ فرصتیں پیدا کر کے اعمالِ صالحہ کا اہتمام کیا جائے۔ ”بوقتِ صبح مومن اور شام کو کافر۔“ اس کا مفہوم یہ ہے کہ صبح کو ایمان سے متصف اور اعمالِ صالحہ سے مزین، لیکن شام کو کفر کی دلدل میں پھنسا ہوا اور کفر یہ اعمال کرتا ہوا نظر آئے گا اور یہ معنی بھی کیا گیا ہے صبح کو اللہ تعالی کی حرام کردہ چیزوں کو حرام سمجھے، لیکن شام کو ان کو حلال تصور کرے گا۔ مطلب یہ ہے کہ حالات ایسا رخ اختیار کریں کہ انسان کو اپنے بدل جانے کی کوئی سمجھ نہیں آئے گی، وہ لاشعور سا لگ رہا ہوگا۔ اب ایسے ہی ہو رہا ہے کہ ایک انسان اچھا بھلا نیک پرہیزگار نظر آتا ہے، لیکن کچھ دنوں کے بعد جب اس سے ملاقات ہوتی ہے تو اس کی روحانی کیفیت بگڑ چکی ہوتی ہے اور نماز جیسے فریضے کو ترک کر چکا ہوتا ہے، کوئی سود کھانے کی وجہ سے گر چکا ہوتا تو کسی سے اچانک قتل ہو جاتا ہے، کوئی دوسرے خاندان کی بچی کی حرمتوں کو پامال کرنے کی کوشش کرتا ہے تو کوئی دوسرے کے مال کو ہڑپ کر جانے کی سوچ رہا ہوتا ہے۔ تاجروں کو کوئی شعور نہیں کہ ان کی تجارت شرعی اصولوں پر مبنی ہے یا نہیں، اپریل ۲۰۰۹ء کی بات ہے کہ ایک تاجر نے ایک شرعی قاعدے کو نظر انداز کر کے سودا کیا، اسے اس وجہ سے دو دنوں کے اندر اڑتالیس لاکھ روپے کا نقصان ہوا۔ خلاصہ کلام یہ ہے کہ لوگ دنیا میں بہت زیادہ دلچسپی لینے والے اور اس کے حریص ہوں گے اور ان کے دینی معاملات ڈگمگا ئیں گے۔"}],[3642,"سیدنا حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے دجال کا ذکر کیا گیا، آپ صلی اللہ علیہ وسلم نے فرمایا: ”دجال کی فتنے کی نسبت مجھے خود تمھارے بعض افراد کے فتنوں کا زیادہ ڈر ہے، جو آدمی دجال سے پہلے والے فتنوں سے نجات پا گیا وہ اس کے فتنے سے بھی چھٹکارا حاصل کر لے گا اور ابتدا سے دنیا سے جو چھوٹا بڑا فتنہ منظرِ عام پر آیا وہ فتنۂ دجال کی خاطر تھا۔“","",{"t":"آپس کے فتنے بھی دجال سے کم نہیں","k":"أخرجه أحمد: ۵/ ۳۸۹، والبزار: ۳۳۹۱\n(الصحيحة: ۳۰۸۲)"}],[3643,"سیدنا حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت پر ایسا (کٹھن) زمانہ آئے گا کہ وہ دجال کی تمنا کرنے لگ جائیں گے۔“ میں نے کہا: اے اللہ کے رسول! میرے ماں باپ آپ پر قربان ہوں! ایسے کیوں ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ مشقت یا بیماری میں پڑنے کی وجہ سے (ایسی خواہش کرنے لگیں گے)۔“","",{"t":"آپس کے فتنے بھی دجال سے کم نہیں","k":"أخرجه الطبراني في \"المعجم الأوسط\": ۱/ ۲۵۹\n(الصحيحة: ۳۰۹۰)","e":"صحابۂ کرام کے دور سے لے کر آج تک کئی مسلمان سنگین فتنوں میں مبتلا رہے ہیں اور دجال کے آنے تک رہیں گے، آج بھی کئی مسلمان آزمائشوں کی بھٹیوں میں جل رہے ہیں۔ اگر کوئی فقر و فاقے کی آزمائش میں مبتلا ہے تو کوئی ظلم و ستم کی چکی میں پس رہا ہے، اگر کوئی عورت اپنے خاوند کے جبر و قہر کا نشانہ بنی ہوئی ہے تو کوئی اپنی بیٹیوں کی وجہ سے ذلیل ہو چکا ہے، اگر کسی مسلمان پر کافروں کا تسلط ہے تو کوئی اسلامی سلطنت میں ہی مجبور و مقہور نظر آتا ہے، اگر کوئی بے گناہ قتل ہو رہا ہے تو کسی کی زندگی اجیرن بن چکی ہے۔ علی ہذا القیاس۔ قارئین کرام! خوشحال اور دوسروں کا درد نہ رکھنے والے لوگ ان حقائق کو تسلیم نہیں کریں گے۔ مقصود یہ ہے کہ مسلمانوں کے پاس قرآن و حدیث کی روشنی میں بصیرت ہونی چاہیے تاکہ وہ پر فتن ادوار میں اپنے آپ کو راہِ صواب پر گامزن رکھنے کے لیے اپنے لیے راہ بنا سکیں۔"}],[3644,"سیدنا حذیفہ رضی اللہ عنہ کہتے ہیں: لوگ رسول اللہ صلی اللہ علیہ وسلم سے خیر کے بارے میں سوال کرتے تھے اور میں شر کے بارے میں دریافت کرتا تھا تاکہ اس میں مبتلا نہ ہو جاؤں۔ (ایک دن) میں نے کہا: اے اللہ کے رسول! ہم جاہلیت اور شر کا زمانہ گزار رہے تھے، اللہ تعالی نے اسلام، جسے ہم نے قبول کیا، کو اور آپ کو ہماری طرف بھیجا۔ (اب سوال یہ ہے کہ) کیا اس خیر کے بعد پھر شر (کا غلبہ ہوگا) جیسا کہ پہلے تھا؟ آپ صلی اللہ علیہ وسلم نے تین دفعہ فرمایا: ”حذیفہ! اللہ کی کتاب پڑھو اور اس کے احکام پر عمل کر۔“ میں نے کہا: اے اللہ کے رسول! کیا اُس شر کے بعد پھر خیر ہوگی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں۔“ میں نے کہا: اس سے بچنے کا کیا طریقہ ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تلوار۔“ میں نے کہا: کیا اس شر کے بعد پھر خیر ہوگی؟ اور ایک روایت میں ہے کہ کیا تلوار کے بعد خیر کا کوئی حصہ باقی رہے گا؟ (یعنی لڑائی کے بعد اسلام باقی رہے گا؟) آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں۔“ اور ایک روایت میں ہے کہ ”امارت (اور جماعت) تو قائم رہے گی، لیکن معمولی چون و چرا اور دلوں میں نفرتیں اور کینے ہوں گے اور ظاہری صلح، لیکن باطن لڑائی ہوگی۔“ میں نے کہا: کینے کا کیا مطلب ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”میرے بعد ایک قوم یا مختلف حکمران ہوں گے جو میری سنت پر عمل نہیں کریں گے اور میری سیرت کے علاوہ کوئی اور سیرت اختیار کریں گے، تو ان کے بعض امور کو اچھا سمجھے گا اور بعض کو برا اور ان میں ایسے لوگ بھی منظرِ عام پر آئیں گے جو انسانوں کے روپ میں ہوں گے، لیکن ان کے دل شیطانی ہوں گے۔“ ایک روایت میں ہے: میں نے کہا: ظاہری صلح باطن لڑائی اور دلوں میں کینہ، ان چیزوں کا کیا مطلب ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”لوگوں کے دل (ان خصائل حمیدہ) کی طرف نہیں لوٹیں گے، جن سے وہ پہلے متصف ہوں گے۔“ میں نے کہا: کیا اس خیر کے بعد بھی شر ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ہاں، اندھا دھند فتنہ ہوگا، اور (اس میں ایسے لوگ ہوں گے کہ گویا کہ) وہ جہنم کے دروازوں پر کھڑے داعی ہیں، جو آدمی ان کی بات مانے گا وہ اس کو جہنم میں پھینک دیں گے۔“ میں نے کہا: اے اللہ کے رسول! ایسے لوگوں کی صفات بیان کرو۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”وہ ہماری نسل کے ہوں گے اور ہماری طرح باتیں کریں گے۔“ میں نے کہا: اے اللہ کے رسول! اگر ایسا زمانہ مجھے پالے تو میرے لیے کیا حکم ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”مسلمانوں کی جماعت اور ان کے حکمران کو لازم پکڑے رکھنا، امیر کی بات سننا اور ماننا۔ اگرچہ تیری پٹائی کر دی جائے اور تیرا مال لوٹ لیا جائے پھر بھی ان کی بات سننا اور اطاعت کرنا۔“ میں نے کہا: اگر سرے سے مسلمانوں کی جماعت ہو نہ حکمران (تو پھر میں کیا کروں)؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”تمام فرقوں سے کنارہ کش ہو جانا، اگرچہ کسی درخت کے تنے کے ساتھ چمٹنا پڑے، یہاں تک کہ تجھے موت پالے اور تو اسی حالت میں ہو۔“ اور ایک روایت میں ہے: ”حذیفہ! کسی درخت کے تنے کا ساتھ چمٹ کر مرنا ان حکمرانوں کی اطاعت کرنے سے بہتر ہوگا۔“ اور ایک روایت میں ہے: ”اگر ان دنوں میں تجھے اللہ کی زمین میں کوئی خلیفہ مل جائے تو اس کو لازم پکڑنا، اگرچہ وہ تیری پٹائی کرے اور تیرا مال چھین لے اور اگر تجھے کوئی خلیفہ نظر نہ آئے تو کسی (گوشۂ) زمین میں بھاگ جانا، حتی کہ تجھے موت آ جائے اور تو کسی درخت کے تنے کے ساتھ چمٹا ہوا ہو۔“ میں نے کہا: پھر کیا ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”پھر دجال ظاہر ہوگا۔“ میں نے کہا: وہ کون سی علامت لے کر آئے گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہر یا پانی اور آگ کے ساتھ آئے گا، جو اس کی نہر میں داخل ہوا اس کا اجر ضائع اور گناہ ثابت ہو جائے گا اور جو اس کی آگ میں داخل ہوا اس کا اجر ثابت ہو جائے گا اور اس کا جرم مٹ جائے گا۔“ میں نے کہا: اے اللہ کے رسول! دجال کے بعد کیا ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”عیسی بن مریم۔“ میں نے کہا: پھر کیا ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”اگر اس وقت تیری گھوڑی کا بچہ پیدا ہوا تو وہ ابھی تک اس قابل نہیں ہوگا کہ تو اس پر سواری کر سکے، کہ قیامت قائم ہو جائے گی۔","",{"t":"آپ صلی اللہ علیہ وسلم کی خیر و شر کی لگائی ہوئی ترتیب مختلف امارتوں، فتنوں اور تفرقہ بازیوں کے ادوار کو کیسے گزارا جائے؟","k":"قد جاء هذا الحديث مطولا و مختصرا من طرق، جمعت هنا فوائدها، وضممت اليه زوائدها في أماكنها المناسبة للسياق - (لكن ما ميزنا الزوائد) الطريق الأول: أخرجه البخاري: ۳۶۰۶، ۷۰۸۴، ومسلم: ۶/ ۲۰، وأبو عوانة: ۵/ ۵۷۴، والطبراني في \"مسند الشامين\": ص ۱/ ۱۰۹، والداني في \"الفتن\": ق ۱/ ۴، وابن ماجه ببعضه: ۲/ ۴۷۵ الثانية: أخرجه مسلم الثالثة: أخرجه أبو عوانة: ۵/ ۴۷۶، وأبو داود: ۴۲۴۴ - ۴۲۴۷، والنسائي في \"الكبرى\": ۵/ ۱۷/ ۸۰۳۲، والطيالسي في \"مسنده\": ۴۴۲، ۴۴۳، وعبدالرزاق في \"المصنف\": ۱۱/ ۳۴۱/ ۲۰۷۱۱، وأحمد: ۵/ ۳۸۶، ۴۰۳، ۴۰۴، ۴۰۶، والحاكم: ۴/ ۴۳۲، وابن أبي شيبة: ۱۵/ ۸/ ۱۸۹۶۰، ۱۸۹۶۱، ۱۸۹۸۰ الرابعة: أخرجه النسائي في \"الكبرى\": ۵/ ۱۸/ ۸۰۳۳، وابن ماجه: ۲/ ۴۷۶، والحاكم: ۴/ ۴۳۲ الخامسة: أخرجه الطبراني في \"الأوسط\": ۱/ ۲۰۲/ ۲/ ۳۶۷۴\n(الصحيحة: ۲۷۳۹)","e":"پہلے بھی یہ تو ضیح پیش کی جا چکی ہے کہ اسلام ایسا کامل مذہب ہے کہ یہ اہل اسلام کی مکمل رہنمائی کرتا ہے، بالخصوص اس ضمن میں کہ اچھے یا برے حالات میں مسلمان کے شب و روز کیسے گزرنے چاہیں۔ لیکن یہ رہنمائی حاصل کرنے کے لیے مسلمان کا صاحبِ بصیرت ہونا اور صاحبِ علم ہونا یا اہلِ علم سے رابطہ کرنا ضروری ہے، وگرنہ عصر حاضر کی طرح اکثر مسلمان ابن الوقت اختیار کر جاتے ہیں اور شر یا لوگوں کی ہاں میں ہاں ملا کر وقت گزارنے میں عافیت سمجھتے ہیں۔ امام البانی رحمہ اللہ کہتے ہیں: مشکل الفاظ کے معانی: ”السیف“: تلوار کے ذریعے عفت و عصمت کا تحفظ ہوگا۔ قتادہ کہتے ہیں: اس شر سے مراد وہ لوگ ہیں، جو آپ صلی اللہ علیہ وسلم کی وفات کے بعد سیدنا ابو بکر صدیق رضی اللہ عنہ کے زمانے میں مرتد ہو گئے تھے۔ ”بقیۃ“: یعنی جب ہم ان سے لڑیں گے، تو کیا اس لڑائی کے بعد اسلام باقی رہے گا؟ ”أقذاء“: ابن اثیر کہتے ہیں: ”قذاة“ کی جمع ”القذی“ ہے اور ”القذی“ کی جمع ”أقذاء“ ہے۔ لغت میں اس سے مراد وہ مٹی یا بھوسے کے تنکے یا میل کچیل ہے، جو آنکھ میں پڑتی ہے یا پانی میں گرتی ہے۔ حدیث میں اس لفظ کا مفہوم یہ ہے کہ بظاہر مسلمان اکٹھے تو ہوں گے، لیکن ان کے دلوں میں فساد اور کینہ ہوگا۔ ”دخن“: قتادہ کی رائے کے مطابق اس سے مراد کینہ ہے، متن میں مذکور ایک طریق میں اس کی تفسیر یہ بیان کی گئی ہے: ”لوگوں کے دل (ان خصائل حمیدہ) کی طرف نہیں لوٹیں گے، جن سے وہ پہلے متصف ہوں گے۔“ ”جذل“: وہ لکڑی، جو اس مقصد کے لیے گاڑھی جاتی ہے، تا کہ اونٹ اس کے ساتھ خارش کریں۔ ”فُلُوّها“: ابن اثیر نے کہا: گھوڑے یا پالتو خچر وغیرہ کا چھوٹا سا بچڑا۔ میں (البانی) کہتا ہوں: یہ حدیث نبوت کی عظیم نشانیوں میں سے ایک ہے۔ اس میں امت کی خیر خواہی کی گئی ہے۔ آج مسلمانوں کو سب سے زیادہ ضرورت اس امر کی ہے کہ وہ فرقہ بندی اور حزبیت سے چھٹکارا حاصل کریں کہ جس کی وجہ سے ان کا شیرازہ منتشر ہو چکا ہے اور ان کی عظمت وسطوت راکھ بن چکی ہے، انہی وجوہات کی وجہ سے ان کا دشمن ان پر غالب آچکا ہے۔ ارشاد باری تعالی ہے: ﴿وَلَا تَنَازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ﴾۝ (سورۃ انفال: ۴۶) ..... ”آپس میں اختلاف نہ کرو، ورنہ بزدل ہو جاؤ گے اور تمہاری ہوا اکھڑ جائے گی۔“ اہم فائدہ: حافظ ابن حجر کہتے ہیں کہ طبری نے کہا: اس حدیث میں یہ وضاحت بھی کر دی گئی ہے کہ جب مسلمانوں کا ایک حاکم وخلیفہ نہ ہو اور وہ مختلف فرقوں میں بٹ چکے ہوں، تو پھر کسی مخصوص فرقے کی پیروی نہ کرے اور تمام تنظیموں سے علیحدگی اختیار کر لے، بشرطیکہ ایسا کرنے میں کسی شر کا خطرہ نہ ہو، اس موضوع پر مختلف احادیث میں یہی جمع وتطبیق مناسب ہے۔ (صحیحہ: ۲۷۳۹)"}],[3645,"سیدنا عبداللہ بن عمر رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب میری امت متکبرانہ چال چلے گی اور فارس و روم کے بادشاہوں کے بیٹے ان کے خادم ہوں گے تو بدترین لوگ بہترین لوگوں پر مسلط ہو جائیں گے۔“","",{"t":"اس امت کے بدترین لوگ، بہترین لوگوں پر مسلط کب ہوں گے؟","k":"أخرجه ابن المبارك في \"الزهد\": ۱۸۷ - رواية نعيم، والمعافى بن عمران في \"الزهد\": ۲/ ۲۳۸، والترمذي: ۲/ ۴۲ - ۴۳، والعقيلي في \"الضعفاء\": ۴۰۸، وابن عدي في \"الكامل\": ۳/ ۳۲۲/ ۱ وابن حبان أيضا: ۲/ ۲۳۶، وأبو نعيم في \"أخبار أصبهان\": ۱/ ۳۰۸، والبيهقي في \"الدلائل\": ج ۲\n(الصحيحة: ۹۵۶)","e":"ایسے ہی ہوا، جب مسلمانوں نے فارس اور روم کے علاقے فتح کیے اور ان کے مال و دولت کے مالک بنے اور ان کی اولاد کو قیدی بنایا تو رفتہ رفتہ مزاج میں تبدیلی آنا شروع ہوگئی، شر غالب ہوتی گئی اور خیر مغلوب۔ بعد والے اہل خیر کو اس کا شدید بھگتان بھگتنا پڑا، آج تک وہی سلسلے جاری ہیں۔"}],[3646,"سیدنا ابو سعید رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میری امت کے آخری زمانے میں مہدی نکلے گا، اللہ تعالی بارش نازل کرے گا، زمین کھیتیاں اگائے گی، وہ لوگوں کو بہترین مال عطا کریں گے، مویشی زیادہ ہو جائیں گے، امت کی تعداد بڑھ جائے گی اور وہ سات یا آٹھ سال تک زندہ رہے گا۔“","",{"t":"قصۂ امام مہدی","k":"أخرجه الحاكم: ۴/ ۵۵۷ - ۵۵۸\n(الصحيحة: ۷۱۱)"}],[3647,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب حضرت عیسی بن مریم (علیہ السلام) اتریں گے تو مسلمانوں کے امیر مہدی انھیں کہیں گے: آئیں اور نماز پڑھائیں۔ وہ کہیں گے: نہیں، تم ہی ایک دوسرے کے امام و امیر بن سکتے ہو، یہ اللہ تعالی کی طرف سے اس امت کی عزت و آبرو ہے۔“","",{"t":"قصۂ امام مہدی","k":"أخرجه الحارث بن أبي أسامة في \"مسنده\"، واصل الحديث في \"صحيح مسلم\": ۱/ ۹۵ من طريق اخرى عن جابر مرفوعا: ((..... فينزل عيسى ابن مريم صلى الله عليه وسلم فيقول اميرهم: تعال صل لنا، فيقول: لا، ان بعضكم على بعض امراء، تكرمة الله هذه الأمة -))\n(الصحيحة: ۲۲۳۶)","e":"امام البانی رحمہ اللہ کہتے ہیں: اصل حدیث صحیح مسلم میں ہے، جو سیدنا جابر رضی اللہ عنہ سے ہی ایک دوسری سند کے ساتھ مروی ہے، وہ کہتے ہیں کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: «لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي يُقَاتِلُونَ عَلَى الْحَقِّ ظَاهِرِينَ إِلَى يَوْمِ الْقِيَامَةِ -» قَالَ: «فَيَنْزِلُ عِيسَى بْنُ مَرْيَمَ صلى الله عليه وسلم فَيَقُولُ أَمِيرُهُمْ: تَعَالَ صَلِّ لَنَا، فَيَقُولُ: لَا، إِنَّ بَعْضَكُمْ عَلَى بَعْضٍ أَمِيرٌ، تَكْرِمَةَ اللهِ هَذِهِ الْأُمَّةَ -» ..... ”میری امت کا ایک گروہ روزِ قیامت تک حق پر غالب رہے گا۔“ پھر فرمایا: ”حضرت عیسی بن مریم علیہ السلام نازل ہوں گے، مسلمانوں کے امیر ان کو کہیں گے: آئیں اور ہمیں نماز پڑھائیں۔ وہ جواب دیں گے: نہیں، تم خود ایک دوسرے کے امام ہو، یہ اللہ تعالی کی طرف سے اس امت کی عزت ہوگی۔“ اس روایت سے معلوم ہوا کہ وہ امیر امام مہدی ہوں گے۔ وباللہ التوفیق۔ (صحیحہ: ۲۲۳۶)"}],[3648,"سیدنا علی رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”مہدی ہم یعنی اہل بیت سے ہوگا، اللہ تعالی ایک رات میں اس کی اصلاح کر دے گا۔“","",{"t":"قصۂ امام مہدی","k":"رواه ابن ماجه: ۴۰۷۵، وأحمد: ۱/ ۸۴، والعقيلي في \"الضعفاء\": ۴۷۰، وابن عدي: ۲/ ۳۶۰، وأبو نعيم في \"الحلية\": ۳/ ۱۷۷، والطحاوي في \"مشكل الآثار\": ۱/ ۴۴۹\n(الصحيحة: ۲۳۷۱)","e":"اصلاح کرنے کا مطلب یہ ہے کہ اللہ تعالی اس پر رجوع کرے گا، اس کو توفیق دے گا اور اس کی رشد و ہدایت اس کو الہام کرے گا، پہلے اس میں ایسے اوصاف نہیں ہوں گے۔"}],[3649,"سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جس کے پیچھے حضرت عیسی بن مریم (علیہ السلام) نماز پڑھیں گے وہ ہم (یعنی اہل بیت) میں سے ہوگا۔“","",{"t":"قصۂ امام مہدی","k":"عزاه السيوطي في \"الجامع\" لأبي نعيم في \"كتاب المهدي\"، والحديث جاء مفرقا في احاديث اخرى\n(الصحيحة: ۲۲۹۳)","e":"امام البانی رحمہ اللہ کہتے ہیں: اس باب میں کئی احادیث سے صراحت کے ساتھ ثابت ہوتا ہے کہ جس امام کی اقتدا میں حضرت عیسی علیہ السلام نماز ادا کریں گے، وہ امام مہدی ہوں گے۔ یہ روایات امام سیوطی کی کتاب (العرف الوردی: ص ۸۱، ۸۳، ۸۴) میں دیکھی جا سکتی ہیں۔ آپ صلی اللہ علیہ وسلم کی یہ احادیث متواتر ہیں کہ امام مہدی تشریف لائیں گے، ان کا تعلق اہل بیت سے ہوگا، وہ حضرت عیسی علیہ السلام کے ساتھ نکلیں گے اور دجال کو قتل کرنے میں ان کی مدد کریں گے، یہی امام ہیں، جو اپنے زمانے میں اس امت کو نماز پڑھا ئیں گے اور حضرت عیسی علیہ السلام ان کے پیچھے نماز پڑھیں گے۔ (صحیحہ: ۲۲۹۳)"}],[3650,"معاویہ بن قرہ اپنے باپ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”زمین ظلم و ستم سے بھر جائے گی، جب ایسے ہوگا تو اللہ تعالی ایک آدمی بھیجے گا، وہ میرا ہم نام ہوگا، وہ زمین میں ظلم و ستم کی جگہ پر عدل و انصاف عام کر دے گا۔“","",{"t":"قصۂ امام مہدی","k":"أخرجه البزار: ص ۲۳۶ - زوائد ابن حجر، وابن عدي في \"الكامل\": ۱/ ۱۲۹، وأبو نعيم في \"أخبار أصبهان\": ۲/ ۱۶۵، والطبراني في \"الكبير\" و \"الأوسط\"\n(الصحيحة: ۱۵۲۹)","e":"امام البانی رحمہ اللہ کہتے ہیں: شیخ غزالی نے کہا: ”میں تو ایک طالب علم ہوں، بہر حال میرے علم کے مطابق تو کسی واضح حدیث میں امام مہدی کا ذکر نہیں آتا اور اگر کوئی صریح حدیث ہے تو وہ صحیح نہیں ہے۔“ میں (البانی) کہتا ہوں: جناب غزالی! کون سے مشائخ نے آپ جیسے طالب علم کو ایسی روایت کی نفی کرنے کی تلقین کی؟ کیا وہ علما ئے کلام تو نہیں ہیں، جن بیچاروں کے پاس حدیث کا علم ہے نہ روایات حدیث کا؟ اس دعوے کی کیا اہمیت ہے، جبکہ دوسری طرف علمائے حدیث نے مختلف احادیث کی روشنی میں امام مہدی کی آمد کو ثابت کر رکھا ہے۔ امام غزالی کو چاہیے تھا کہ وہ تصحیح و تضعیف کے قانون کو سامنے رکھتے ہوئے قرآن و حدیث اور ان سے صادر ہونے والے احکام و مسائل کا مراجعہ کرتے اور مسلمانوں کو خواہ مخواہ شک میں نہ ڈالتے۔ میرے مسلمان بھائی! عصر حاضر میں اکثر مسلمان راہِ مستقیم سے منحرف ہو چکے ہیں، یہ ذاتی اختراعات اور خود ساختہ آرا کی روشنی میں شریعت کی مختلف نصوص کی وضاحت کرتے ہوئے نظر آتے ہیں۔ کوئی کہتا ہے کہ اب امام مہدی کے خروج کے بعد ہی اسلام کو غلبہ و اقتدار نصیب ہوگا، (ان سے پہلے غلبۂ اسلام کی کوئی صورت نہیں)۔ یہ بے سرو پا دعوی اور ضلالت و گمراہی ہے، جو شیطان نے اکثر لوگوں اور بالخصوص صوفیوں کے دلوں میں القا کر دی ہے۔ حالانکہ امام مہدی کی آمد میں جتنی احادیث نبویہ مروی ہیں، کسی ایک سے بھی یہ دعوی ثابت نہیں ہوتا۔ اتنا ضرور ہے کہ آپ صلی اللہ علیہ وسلم نے مسلمانوں کو ایسے شخص کے ظہور کی خوشخبری سنائی، جو آپ صلی اللہ علیہ وسلم کے اہل بیت میں سے ہوگا اور وہ اسلام کے احکام کی روشنی میں فیصلہ کرنے کے ساتھ ساتھ عدل و انصاف کو عام کر دے گا، حقیقت میں وہ ان مجد دین میں سے ہوگا، جن کو اللہ تعالی ہر صدی کے بعد بھیجتا ہے۔ اس کا یہ معنی نہیں کہ ہم دین کی تجدید کی خاطر علم و عمل کے لیے جد و جہد ترک کر دیں۔ اسی طرح امام مہدی کی آمد کا یہ معنی بھی نہیں کہ ہم زمین میں اللہ تعالی کی شریعت کے نفاذ کے لیے کوئی کوشش نہ کریں اور ان کی آس میں بیٹھ جائیں۔ ہم نے عوام الناس کی جو بے سرو پا باتیں بیان کی ہیں، بعض صوفیوں سمیت کچھ لوگوں کو ان کا علم تو ہے، لیکن جب ان میں یہ وہم پیدا ہوتا ہے کہ امام مہدی کے خروج کا عقیدہ رکھنے سے یہ امور لازم تو آئیں گے، تو وہ فوراً انکار کرنے لگتے ہیں۔ یہ تو ایسے ہی ہے، جیسے کسی نے کہا: اس نے میرا علاج اس چیز کے ساتھ کیا، جس میں بیماری تھی۔ ایسے لوگ معتزلیوں سے مختلف نہیں ہیں کہ جنھوں نے اس بنا پر تقدیر کا انکار کر دیا کہ کچھ لوگ اس سے ”جبر“ کا استدلال کر رہے ہیں۔ یہ بیچارے ایک طرف تو جبر کا جواب نہ دے سکے اور دوسری طرف جس چیز کا عقیدہ رکھنا فرض تھا، اس کا انکار کر دیا۔ ایک فریق کا خیال ہے کہ تاریخ اسلامی شاہد ہے کہ بعض خود غرضوں اور بیوقوفوں نے امام مہدی کے قصے سے ناجائز فائدہ اٹھا کر لوگوں کو زبردست فتنوں میں مبتلا رکھا ہے، مثلاً جہیمان سعودی کا حرم مکی میں برپا کیا ہوا فتنہ۔ اس لیے ضروری ہے کہ سرے سے امام مہدی کی آمد کا ہی انکار کر دیا جائے، تاکہ فتنہ باز لوگوں کے فتنے دب جائیں، شیخ غزالی نے بھی اپنے کلام کے آخر میں اس چیز کی طرف اشارہ کیا تھا۔ اس فاسد خیال کے حق میں رائے دینے والے اُن باطل پرستوں کی طرح ہیں جنھوں نے آخری زمانے میں حضرت عیسی علیہ السلام کے نزول کا انکار اس بنا پر کیا ہے، کہ بعض کذاب اور دجال لوگوں نے فتنہ برپا کرنے کے لیے اپنے آپ کو ”مسیح موعود“ ظاہر کیا ہے، مثال کے طور پر مرزا غلام احمد قادیانی۔ شیخ شلتوت جیسوں نے واضح طور پر حضرت عیسی علیہ السلام کے نزول کا انکار کر دیا اور بعض وضاحت تو نہیں کرتے، لیکن ان کی زبانیں اس قسم کے خیالاتِ فاسدہ اگلتی رہتی ہیں۔ ممکن ہے کہ میں حتمی طور پر یہ دعوی کر دوں کہ جن لوگوں نے امام مہدی کی آمد کا انکار کیا، انھوں نے حضرت عیسی علیہ السلام کے نزول کا بھی انکار کر دیا۔ میرے ہاں ان منکرین کی مثال اس شخص کی طرح ہے، جو اللہ تعالی کی الوہیت کا انکار اس چیز کو بنیاد بنا کر دے کہ بعض فرعونوں نے بھی الوہیت کا دعوی کیا ہے، اس لیے سرے سے اللہ تعالی کے معبود ہونے کا ہی انکار کر دیا جائے، تاکہ فراعنہ باز آجائیں۔ ﴿فَهَلْ مِنْ مُدَّكِرٍ﴾۝ (سورۃ قمر: ۱۵) ...... ”کیا کوئی ہے نصیحت حاصل کرنے والا؟“ (صحیحہ: ۱۵۲۹) ان بیچاروں کی مثال اس شخص کی طرح ہے جو ریت کی تپش سے بچنے کے لیے آگ میں گھس گیا، حق یہ ہے کہ شرعی علم و عمل کی روشنی میں فتنوں کا رد کیا جائے۔"}],[3651,"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے آج رات اپنے آپ کو خواب میں کعبہ کے پاس دیکھا، میں نے ایک گندی رنگ کا آدمی دیکھا تھا، اس رنگ میں وہ انتہائی خوبصورت آدمی تھا، اس کی بہت خوبصورت زلفیں تھیں، اس نے کنگھی کر رکھی تھی اور ان سے پانی کے قطرے ٹپک رہے تھے، اس نے دو آدمیوں یا دو آدمیوں کے کندھوں پر ٹیک لگا رکھی تھی اور وہ بیت اللہ کا طواف کر رہا تھا۔ میں نے پوچھا: یہ آدمی کون ہے؟ کہا گیا کہ یہ مسیح بن مریم (علیہ السلام) ہیں۔ پھر اچانک میں نے ایک اور آدمی دیکھا جو چھوٹے گھونگھریالے بالوں والا تھا، اس کی دائیں آنکھ کانی تھی اور وہ خوشئہ انگور میں ابھرے ہوئے دانے کی طرح لگتی تھی۔ میں نے پوچھا: یہ کون ہے؟ مجھے کہا گیا کہ یہ مسیح دجال ہے۔“","",{"t":"حضرت عیسی علیہ السلام کا حلیہ مبارک","k":"أخرجه مالك في \"الموطأ\": ۳/ ۱۰۷، ومن طريقه أخرجه البخاري: ۵۹۰۲، ومسلم: ۱/ ۱۰۷\n(الصحيحة: ۳۹۸۳)"}],[3652,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ”اس ذات کی قسم جس کے ہاتھ میں ابوالقاسم کی جان ہے! حضرت عیسی بن مریم (علیہ السلام) انصاف پسند امام اور عدل پسند حکمران بن کر ضرور نازل ہوں گے، وہ صلیب کو توڑ دیں گے، خنزیر کو قتل کر دیں گے، تعلقات میں صلح صفائی کریں گے، عداوت ختم ہو جائے گی، ان پر مال پیش کیا جائے گا لیکن وہ قبول نہیں کریں گے، اگر وہ میری قبر پر کھڑے ہوئے اور کہا: اے محمد! تو میں ان کو جواب دوں گا۔“","",{"t":"حضرت عیسی علیہ السلام کی صفات","k":"أخرجه أبو يعلى في \"مسنده\": ۴/ ۱۵۵۲، وأخرجه البخاري: ۳۴۴۸، ومسلم: ۱/ ۹۳ دون قوله: ((وليصلحن ذات البين، وليذهبن الشحناء))، والفقرة الثانية منهما عند مسلم و غيره\n(الصحيحة: ۲۷۳۳)","e":"یہ بات یقینی ہے کہ نہ حضرت عیسی علیہ السلام نے آپ صلی اللہ علیہ وسلم کو آواز دینی ہے اور نہ آپ صلی اللہ علیہ وسلم نے ان کا جواب دینا ہے، معلوم ہوتا ہے کہ اس سے مراد حضرت عیسی علیہ السلام کی مقبولیت کی نشاندہی کی گئی ہے یا پھر ترغیب دلائی جا رہی ہے۔ واللہ اعلم۔"}],[3653,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”حضرت عیسی (علیہ السلام) کے بعد والی زندگی کے لیے خوشخبری ہے، حضرت عیسی (علیہ السلام) کے بعد والی زندگی کے لیے خوشخبری ہے، آسمان کو برسنے کی اور زمین کو کھیتیاں اگانے کی (کھلی) اجازت دی جائے گی۔ اگر تم اس وقت صفا پہاڑی پر بھی بیج کاشت کرو گے تو وہ اگ آئے گا۔ (لوگوں میں) ایک دوسرے سے فوقیت و برتری لے جانے کی کوئی تمنا نہیں ہوگی، حسد و بغض ختم ہو جائے گا اور (اتنا امن ہوگا کہ) آدمی شیر کے پاس سے گزر جائے گا، وہ اسے کوئی نقصان نہیں پہنچائے گا اور آدمی سانپ کے اوپر سے گزر جائے گا، وہ اسے کوئی تکلیف نہیں دے گا۔ لوگوں میں ایک دوسرے سے سبقت لے جانے کی کوئی تڑپ باقی نہیں رہے گی اور نہ کوئی حسد و بغض ہوگا۔“","",{"t":"حضرت عیسی علیہ السلام کی صفات","k":"رواه أبوبكر الأنباري في \"حديثه\": ج ۱ ورقة ۶/ ۱، والديلمي: ۲/ ۱۶۱، والضياء في \"المنتقى من مسموعاته بمرو\": ۱/ ۱۲۷\n(الصحيحة: ۱۹۲۶)","e":"اس میں حضرت عیسی علیہ السلام کے دور میں امن و امان، محبت و مودت اور مال و دولت کی فراوانی کی ایک جھلکی پیش کی گئی ہے۔"}],[3654,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”جب حضرت عیسی بن مریم (علیہ السلام) اتریں گے تو مسلمانوں کے امیر مہدی انھیں کہیں گے: آئیں اور نماز پڑھائیں۔ وہ کہیں گے: نہیں، تم ہی ایک دوسرے کے امام و امیر بن سکتے ہو، یہ اللہ تعالی کی طرف سے اس امت کی عزت و آبرو ہے۔“","",{"t":"حضرت عیسی علیہ السلام کی صفات","k":"أخرجه الحارث بن أبي أسامة في \"مسنده\"، واصل الحديث في \"صحيح مسلم\": ۱/ ۹۵ من طريق اخرى عن جابر مرفوعا: ((..... فينزل عيسى ابن مريم صلى الله عليه وسلم فيقول اميرهم: تعال صل لنا، فيقول: لا، ان بعضكم على بعض امراء، تكرمة الله هذه الأمة -))\n(الصحيحة: ۲۲۳۶)"}],[3655,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”تم میں سے جو حضرت عیسی بن مریم (علیہ السلام) کو پالے، تو انھیں میرا سلام پہنچائے۔“","",{"t":"آپ صلی اللہ علیہ وسلم کا حضرت عیسی علیہ السلام کو سلام بھیجنا","k":"أخرجه الحاكم: ۴/ ۵۴۵\n(الصحيحة: ۲۳۰۸)","e":"تمام مسلمان یہ حدیث ذہن نشین کریں اور اپنی نسل کو اس کی تعلیم دیں، تاکہ جس کے زمانے میں حضرت عیسی علیہ السلام کا ظہور ہو وہ ان کو آپ صلی اللہ علیہ وسلم کا سلام پہنچائے۔"}],[3656,"سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”میں نے آج رات اپنے آپ کو خواب میں کعبہ کے پاس دیکھا، میں نے ایک گندی رنگ کا آدمی دیکھا تھا، اس رنگ میں وہ انتہائی خوبصورت آدمی تھا، اس کی بہت خوبصورت زلفیں تھیں، اس نے کنگھی کر رکھی تھی اور ان سے پانی کے قطرے ٹپک رہے تھے، اس نے دو آدمیوں یا دو آدمیوں کے کندھوں پر ٹیک لگا رکھی تھی اور وہ بیت اللہ کا طواف کر رہا تھا۔ میں نے پوچھا: یہ آدمی کون ہے؟ کہا گیا کہ یہ مسیح بن مریم (علیہ السلام) ہیں۔ پھر اچانک میں نے ایک اور آدمی دیکھا جو چھوٹے گھونگھریالے بالوں والا تھا، اس کی دائیں آنکھ کانی تھی اور وہ خوشئہ انگور میں ابھرے ہوئے دانے کی طرح لگتی تھی۔ میں نے پوچھا: یہ کون ہے؟ مجھے کہا گیا کہ یہ مسیح دجال ہے۔“","",{"t":"دجال اور اس کی شکل اور صفات","k":"أخرجه مالك في \"الموطأ\": ۳/ ۱۰۷، ومن طريقه أخرجه البخاري: ۵۹۰۲، ومسلم: ۱/ ۱۰۷\n(الصحيحة: ۳۹۸۳)"}],[3657,"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دجال کانا ہوگا، اس کا رنگ سفید ہوگا، ایسے لگتا ہے کہ اس کا سر چھوٹے مہلک سانپ (کے سر) کی طرح (یعنی اس کا سر بہت چھوٹا) ہوگا۔ لوگوں میں عبدالعزی بن قطن اس کے زیادہ مشابہ ہے، (ذہن نشین کر لو کہ مشابہت میں پڑ کر) ہلاک ہونے والے ہلاک ہوتے رہیں، بیشک تمھارا رب کانا نہیں ہے۔“","",{"t":"دجال اور اس کی شکل اور صفات","k":"أخرجه ابن حبان في \"صحيحه\" ۱۹۰۰ - موارد، وأحمد: ۱/ ۲۴۰ و ۳۱۳، وأبو أسحاق الحربي في \"غريب الحديث\" ۵/ ۷۳/ ۱ و ۹۳/ ۱، وابن منده في \"التوحيد\" ۸۳/ ۱\n(الصحيحة: ۱۱۹۳)","e":"امام البانی رحمہ اللہ کہتے ہیں: اس حدیث سے واضح طور پر پتہ چل رہا ہے کہ دجال کا تعلق بشریت سے ہے، اس میں بشری کی صفات پائی جاتی ہیں، جیسے وہ عبدالعزی بن قطن کے ساتھ مشابہ ہے۔ بعض لوگوں کا خیال ہے کہ دجال سے مراد یورپی تہذیب اور اس کی زینت و سجاوٹ اور حسن و دلکشی اور فتنے مراد ہیں، لیکن اس حدیث سمیت کئی دلائل سے اس تاویل کا رد ہوتا ہے۔ سیدھی سی بات ہے کہ دجال ایک بشر ہے اور اس کا فتنہ سب سے بڑا ہے، اس میں تاویل کی کوئی گنجائش نہیں ہے۔ اللہ تعالی ہمیں اس سے محفوظ رکھے۔ (صحیحہ: ۱۱۹۳)"}],[3658,"سیدہ عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دجال کے زمانے کی شدید مزاحمتوں کا ذکر کیا۔ میں نے کہا: اے اللہ کے رسول! اس وقت عرب کہاں ہوں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”عائشہ! ان دنوں عرب تھوڑے ہوں گے۔“ میں نے کہا: تو پھر کون سی چیز مومنوں کو کھانے سے کفایت کرے گی؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”جو فرشتوں کو کفایت کرتی ہے، ..... تسبیح، تکبیر، تحمید اور تہلیل۔“ میں نے کہا: ان دنوں میں کون سا مال بہتر ہوگا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: ”ایسا خادم جو اپنے آقاؤں کو پانی پلا دے گا، رہا مسئلہ کھانے کا تو وہ تو (سرے سے) نہیں ہوگا۔“","",{"t":"دجال اور اس کی شکل اور صفات","k":"أخرجه أحمد: ۶/ ۷۵ - ۷۶، ۱۲۵، وأبو يعلى: ۸/ ۷۸/ ۴۶۰۷\n(الصحيحة: ۳۰۷۹)","e":"دجال مسلمانوں کے حق میں بہت بڑا فتنہ ہوگا، اس کی تصدیق نہ کرنے والے مسلمانوں کا مال اس کے پیچھے چل پڑے گا اور ان کے پاس کچھ نہ رہے گا۔ اس کی وجہ سے مزید تکالیف کا معاملہ اس کے علاوہ ہوگا۔"}],[3659,"سیدنا ابی بن کعب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”دجال کی آنکھ شیشے کی طرح سبز ہوگی اور ہم عذاب قبر سے اللہ تعالی کی پناہ طلب کرتے ہیں۔“","",{"t":"دجال اور اس کی شکل اور صفات","k":"رواه أحمد: ۵/ ۱۲۳ و ۱۲۴، وأبو نعيم في \"أخبار أصبهان\": ۱/ ۲۴۷، ۲۹۴ - ۴۹۵\n(الصحيحة: ۱۸۶۳)"}],[3660,"ربعی بن حراش کہتے ہیں: سیدنا عقبہ بن عمرو رضی اللہ عنہ نے سیدنا حذیفہ رضی اللہ عنہ سے کہا: آیا آپ ہم کو رسول اللہ صلی اللہ علیہ وسلم سے سنی ہوئی کوئی حدیث بیان کریں گے؟ انھوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”بیشک جب دجال نکلے گا تو اس کے ساتھ پانی اور آگ ہوں گے، جو چیز لوگوں کو آگ کی صورت میں نظر آئے گی وہ درحقیقت ٹھنڈا پانی ہوگی اور لوگ جس چیز کو ٹھنڈا پانی تصور کریں گے وہ حقیقت میں جلانے والی آگ ہوگی۔ اگر تم لوگ دجال کو پالو تو اس میں گرنا جو تمھیں آگ کی شکل میں نظر آئے گی، کیونکہ وہ دراصل میٹھا اور ٹھنڈا پانی ہوگا۔“ سیدنا عقبہ نے سیدنا حذیفہ کی تصدیق کرتے ہوئے کہا: میں نے بھی یہ حدیث سنی تھی۔","",{"t":"دجال اور اس کی شکل اور صفات","k":"أخرجه البخاري: ۳۴۵۰، ۷۱۳۰، ومسلم: ۸/ ۱۹۶، وابن أبي شيبة في \"المصنف\" ۱۹۳۵۱، وأحمد: ۵/ ۳۹۵، والمحاملي في \"الأمالي\": ۳۱۵، والطبراني: ۱۷/ ۲۳۱\n(الصحيحة: ۳۵۴۲)"}],[3661,"جنادہ بن ابو امیہ دوسی کہتے ہیں: میں اور میرا دوست ایک صحابی رسول کے پاس گئے اور کہا: ہمیں ایسی حدیث بیان کرو، جو تم نے رسول اللہ صلی اللہ علیہ وسلم سے خود سنی ہو، کسی اور سے نہیں، اگرچہ وہ ہمارے ہاں صادق ہو۔ انھوں نے کہا: جی ہاں، رسول اللہ صلی اللہ علیہ وسلم ہم میں کھڑے ہوئے اور فرمایا: ”میں تمھیں دجال سے ڈراتا ہوں، میں تمھیں دجال سے ڈراتا ہوں، میں تمھیں دجال سے ڈراتا ہوں، ہر نبی نے اپنی امت کو اس سے آگاہ کیا۔ اے میری امت! وہ تم میں نکلے گا۔ وہ گھونگھریالے بالوں والا اور گندی رنگ کا ہوگا، اس کی بائیں آنکھ مٹی ہوئی ہوگی، اس کے پاس جنت اور جہنم ہوگی۔ (درحقیقت) اس کی جہنم، جنت ہوگی اور اس کی جنت، جہنم ہوگی۔ اس کے پاس پانی کی نہر اور روٹیوں کا پہاڑ ہوگا۔ (اسے اتنی قدرت دی جائے گی کہ) ایک جان کو قتل کر کے اسے زندہ کر سکے گا، مزید اسے اس قسم کا تسلط نہیں دیا جائے گا۔ وہ آسمان سے بارش برسائے گا، لیکن زمین سے کوئی چیز نہیں اگائے گی۔ وہ زمین میں چالیس دن ٹھہرے گا، لیکن ہر جگہ پر پہنچے گا۔ وہ چار مساجد کے قریب نہیں آ سکے گا: مسجد حرام، مسجد نبوی، مسجد مقدس اور کوہ طور۔ اگر کچھ اختیارات کی وجہ سے تم پر (اس کی اللہ تعالی سے) مشابہت پڑنے لگے، تو ذہن میں رکھنا کہ اللہ تعالی کانا نہیں ہے۔“ یہ بات دو دفعہ ارشاد فرمائی۔","",{"t":"دجال اور اس کی شکل اور صفات","k":"أخرجه ابن أبي شيبة في \"المصنف\": ۱۵/ ۱۴۷ - ۱۴۸، وأحمد: ۵/ ۴۳۵، وفي \"السنة\": رقم ۱۰۱۶\n(الصحيحة: ۲۹۳۴)"}],[3662,"عمر بن ثابت انصاری کہتے ہیں کہ مجھے ایک صحابی رسول نے بیان کیا کہ ایک دن نبی کریم صلی اللہ علیہ وسلم نے انھیں دجال سے آگاہ کرتے ہوئے فرمایا: ”جان لو کہ کوئی بھی اپنے رب کو مرنے سے پہلے نہیں دیکھ سکتا اور اس دجال کی آنکھوں کے درمیان (ک ف ر) لکھا ہوگا، اس کے عمل کو ناپسند کرنے والا ہر شخص یہ الفاظ پڑھ لے گا۔“","",{"t":"دجال اور اس کی شکل اور صفات","k":"أخرجه مسلم: ۸/ ۱۹۳، والترمذي: ۲۲۳۶، وابن منده في \"المعرفة\": ۲/ ۲۸۷/ ۲\n(الصحيحة: ۲۸۶۲)","e":"مومنوں کو ذہن نشین کر لینا چاہیے کہ موت سے پہلے اللہ تعالی کا دیدار ناممکن ہے، اس لیے اگر کوئی ان کی زندگی میں رب ہونے کا دعوی کر دے تو اسے فوراً جھٹلا دیا جانا چاہیے۔"}],[3663,"ابو قلابہ کہتے ہیں: میں نے مدینہ میں ایک آدمی دیکھا، لوگ اس کے ارد گرد چکر لگا رہے تھے اور وہ کہہ رہا تھا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا، وہ آدمی صحابی رسول تھا اور میں نے اسے یہ کہتے ہوئے سنا: ”تمھارے بعد انتہائی جھوٹا اور گمراہ کن آدمی پیدا ہوگا، اس کے سر کے بال گھونگھریالے (یا بل دیے ہوئے) ہوں گے، وہ کہے گا: میں تمھارا رب ہوں۔ جس آدمی نے اسے یوں جواب دیا: تو ہمارا رب نہیں ہے، ہمارا رب تو اللہ ہے، ہم نے اس پر توکل کیا، اسی کی طرف رجوع کیا اور ہم تیرے شر سے اللہ تعالی کی پناہ مانگتے ہیں۔ تو اس پر اس کا کوئی بس نہیں چلے گا۔“","",{"t":"دجال اور اس کی شکل اور صفات","k":"أخرجه الامام أحمد: ۵/ ۳۷۲\n(الصحيحة: ۲۸۰۸)","e":"امام البانی رحمہ اللہ نے کہا: اس حدیث مبارک میں صراحت کی گئی ہے کہ دجال ایک شخص ہے، جس کا سر اور بال ہوں گے۔ اس سے مراد فساد نہیں ہے، جیسا کہ بعض ضعیف الایمان لوگوں کو وہم ہوا ہے۔ (صحیحہ: ۲۸۰۸) معلوم ہو کہ دجال کو دیکھ کر یہ دعا پڑھی جائے: لَسْتَ رَبَّنَا، لَكِنْ رَبُّنَا اللهُ، عَلَيْهِ تَوَكَّلْنَا، وَإِلَيْهِ أَنَبْنَا، نَعُوذُ بِاللهِ مِنْ شَرِّكَ۔"}],[3664,"سیدنا ابو بکر صدیق رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے ہم کو بیان کیا: ”مشرقی سر زمین، جسے خراسان کہتے ہیں، سے دجال نمودار ہوگا، اس کی پیروی کرنے والے لوگوں کے چہرے گویا کہ تہ بہ تہ ڈھالیں ہیں۔“","",{"t":"دجال کی جائے خروج","k":"أخرجه الترمذي: ۳/ ۲۳۴، وابن ماجه: ۲/ ۵۰۶، والحاكم: ۴/ ۵۲۷، وأحمد: ۱/ ۷ و ۴، والضياء في \"المختارة\": ۳۳ - ۳۷ بتحقيقي\n(الصحيحة: ۱۵۹۱)","e":"امام عبدالرحمن مبارکپوری کہتے ہیں: ماورا ء النہر اور عراق کے علاقوں کے درمیان خراسان کے معروف علاقے ہیں۔ اب ہرات کو خراسان کہتے ہیں، جس کا بیشتر حصہ آپ صلی اللہ علیہ وسلم کی پیشین گوئی میں مذکورہ خراسان کا ہے، بالکل ایسے ہی سمجھیں جیسے دمشق کو شام کہتے ہیں۔ (حالانکہ احادیث میں مذکورہ شام جزیرہ نما عرب کا شامل علاقہ ہے، جو موجودہ شام، اناطولیہ سمیت، اردن اور فلسطین سے عسقلان پر مشتمل ہے۔) رہا مسئلہ اس کی پیروی کرنے والے اس حدیث میں مذکورہ لوگوں کا، تو یہ پیدائشی اوصاف ترک اور ازبک لوگوں میں پائے جاتے ہیں۔ (تحفۃ الاحوذی: ۳/ ۲۳۴) جغرافیائی حدود میں تبدیلی کی وجہ سے علاقوں کے قدیم اور جدید ناموں میں اختلاف پایا جاتا رہا ہے۔","i":"§دجال کی جائے خروج"}],[3665,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ”اصفہان کے ستر ہزار یہودی دجال کے پیچھے لگیں گے (پیروی کریں گے) جن کے جسموں پر سبز رنگ کی چادریں ہوں گی۔“","",{"t":"ستر ہزار یہودی دجال کی پیروی کریں گے","k":"أخرجه مسلم: ۸/ ۲۰۷، وابن حبان: ۶۷۶۰، وابن عساکر في \"تاريخ دمشق\": ۲/ ۲۵۰ - مصورة المدينة\n(الصحيحة: ۳۰۸۰)","e":"یہودیوں کا ماضی کا بھی حق کی مخالفت سے بھر پڑا ہے اور مستقبل کا یہ حال ہے۔"}],[3666,"سیدنا جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے، آپ صلی اللہ علیہ وسلم حرہ کے ایک ٹیلے سے جھانکے اور فرمایا: ”جب دجال کا ظہور ہوگا تو مدینہ بہترین سر زمین ثابت ہوگی، اس کی طرف آنے والے ہر راستے پر فرشتہ ہوگا، اس لیے دجال اس میں داخل نہیں ہو سکے گا۔ جب معاملہ یہ ہوگا تو مدینہ تین دفعہ اپنے باشندوں کو جھٹکا دے گا، (مدینہ میں رہنے والا) ہر منافق مرد اور عورت دجال کی طرف نکل جائے گا، زیادہ تر جانے والی عورتیں ہوں گی، یہ ”یوم التخلیص“ ہوگا، اس دن مدینہ اپنے اندر پائی جانے والی خباثت اس طرح نکال دے گا، جیسے دھونکنی لوہے کی میل کچیل کو صاف کر دیتی ہے۔ دجال کے ساتھ ستر ہزار (۷۰،۰۰۰) یہودی ہوں گے، ہر ایک نے زرہ زیب تن کی ہوگی اور ہر ایک کے پاس آراستہ کی ہوئی ایک تلوار ہوگی، جہاں پانی کے نالے جمع ہوتے ہیں وہاں اس کا ڈیرہ بنایا جائے گا۔“ پھر آپ صلی اللہ علیہ وسلم نے فرمایا: ”نہ (ماضی میں) ایسا فتنہ تھا اور نہ تا قیامت ہوگا، جو دجال کے فتنے سے سنگین ہو۔ ہر نبی نے اپنی امت کو اس سے متنبہ کیا اور میں تمھیں اس کی ایسی علامت بتاتا ہوں جو کسی نبی نے نہیں بتائی۔“ پھر آپ صلی اللہ علیہ وسلم نے اپنا ہاتھ اپنی آنکھ پر رکھا اور فرمایا: ”میں گواہی دیتا ہوں کہ اللہ تعالی کانا نہیں ہے (اور دجال کانا ہوگا)۔“","",{"t":"دجال مدینہ منورہ میں داخل نہیں ہوگا مدینہ منورہ میں رہنے والے منافق دجال کے پاس کیسے پہنچیں گے؟","k":"أخرجه الامام أحمد: ۳/ ۲۹۲، و رواه الطبراني في \"الاوسط\": ۱/ ۱۱۹/ ۲/ ۲۳۵۴ ولم يسق لفظه بتمامه\n(الصحيحة: ۳۰۸۱)","i":"§دجال مدینہ منورہ میں داخل نہیں ہوگا مدینہ منورہ میں رہنے والے منافق دجال کے پاس کیسے پہنچیں گے؟"}],[3667,"سیدنا ابوذر رضی اللہ عنہ کہتے ہیں: ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (سفر سے واپس آ رہے) تھے، ہم نے ذوالحلیفہ مقام میں پڑاؤ ڈالا، کچھ لوگوں نے مدینہ کی طرف جانے میں عجلت سے کام لیا، رسول اللہ صلی اللہ علیہ وسلم نے وہیں رات گزاری اور ہم بھی آپ کے ساتھ تھے۔ جب صبح ہوئی تو آپ صلی اللہ علیہ وسلم نے ان کے بارے میں پوچھا (کہ وہ کہاں ہیں)؟ بتایا گیا کہ انھوں نے مدینہ کی طرف جانے میں جلدی کی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ”انھوں نے مدینہ اور عورتوں کی طرف جانے میں جلدی کی ہے، عنقریب یہ لوگ مدینہ کو چھوڑ جائیں گے، حالانکہ وہ ان کے لیے بہت بہتر ہوگا۔“ پھر فرمایا: ”کاش میں جانتا ہوتا کہ جب یمن کے جبل وراق سے آگ نکلے گی، وہ بصری میں بیٹھے ہوئے اونٹوں کی گردنوں کو ایسے روشن کر دے گی، جیسے وہ دن کی روشنی میں نظر آتی ہیں۔“","",{"t":"مدینہ منورہ بالآخر خالی ہو جائے گا","k":"أخرجه أحمد: ۵/ ۱۴۴، وابن حبان: ۱۸۹۱\n(الصحيحة: ۳۰۸۳)"}],[3668,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ”لوگ مدینہ کو خیر آباد کہہ دیں گے، حالانکہ وہ ان کے لیے سب سے بہتر ہوگا، (درندے اور پرندے جیسے) روزی کے متلاشی جانور اس کو اپنی آماجگاہ بنا لیں گے۔ سب سے آخر میں مزینہ قبیلے کے دو چرواہے اپنی بکریوں کو ڈانتتے لکارتے مدینہ کی طرف آئیں گے، (جب پہنچیں گے تو) اسے اجاڑ اور ویران پائیں گا، جب وہ ثنیہ وداع تک پہنچیں گے تو چہروں کے بل گر پڑیں گے۔“","",{"t":"مدینہ منورہ بالآخر خالی ہو جائے گا","k":"أخرجه البخاري: ۴/ ۷۲ - فتح، ومسلم: ۴/ ۱۲۳، وأحمد: ۲/ ۲۳۴\n(الصحيحة: ۶۸۳)","e":"اگرچہ مدینہ منورہ سے خلافت شام و عراق کی طرف منتقل ہو جانے کو اس حدیث کا مصداق ٹھہرایا گیا ہے، لیکن حقیقت حال یہ ہے کہ یہ حالات قیامت کے قریب ظاہر ہوں گے۔ حافظ ابن حجر نے مختلف شواہد بھی ذکر کیے ہیں۔ (ملاحظہ ہو: فتح الباری: ۴/ ۱۱۱، ۱۱۲)"}],[3669,"سیدنا عدی بن حاتم رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ کو اس کی چار اطراف سے ایک ایک برید تک اس بات سے ممنوع قرار دیا کہ وہاں کے درختوں کے پتے (ڈنڈے وغیرہ کے ذریعے) جھاڑے جائیں یا انھیں کاٹا جائے، ہاں اونٹوں کو ہانکنے کے لیے (کوئی چھڑی وغیرہ) کاٹی جا سکتی ہے۔","",{"t":"حرم مدینہ کی حد","k":"أخرجه أبو داود: ۲۰۳۶، والطبراني في \"المعجم الكبير\": ۱۷/ ۱۱۱/ ۷۲۲\n(الصحيحة: ۳۷۳۴)","e":"۱۲ ہاشمی (۱۲ پاکستانی) میل کا ایک برید بنتا ہے، جو تقریباً ۲۹ کلومیٹر کے برابر ہوتا ہے۔ صحیح بخاری اور صحیح مسلم کی روایت ہے، سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے مدینہ منورہ کے دو حروں کے درمیان والی جگہ کو حرمت والا اور مدینہ کے ارد گرد بارہ میلوں تک کے علاقہ کو ممنوعہ قرار دیا۔ ابو ہریرہ خود کہتے ہیں: اگر مجھے ان دو حروں کے درمیان ہرن بھی مل جائے تو میں اسے خوفزدہ نہیں کرتا۔ ان دو احادیث میں حرم مدینہ کی حد کی تصریح کر دی گئی ہے۔"}]])